/// Router fallback for any path the route table doesn't claim. Returns
/// the canonical 404 HTML for browser clients with `Accept: text/html`,
/// and a small JSON `{schema:"emem.error.v1", code, ...}` envelope for
/// programmatic clients (the same shape every other emem error uses)
/// so an agent sees a typed `not_found` instead of an HTML body it
/// can't parse. Both arms return HTTP 404, no soft 200, no redirect.
/// The browser HTML embeds a 20 s client-side redirect to `/` with an
/// explicit cancel; programmatic callers don't run that script and so
/// see the 404 stay a 404.
/// Every path documented in the OpenAPI spec, harvested once.
///
/// The spec is the canonical machine-readable route list and is already
/// reconciled by `scripts/sync_counts.py`, so suggesting from it means there is
/// no second list to drift out of step with the router.
fn documented_paths() -> &'static [String] {
    static PATHS: std::sync::OnceLock<Vec<String>> = std::sync::OnceLock::new();
    PATHS.get_or_init(|| {
        let spec = openapi_spec();
        let mut v: Vec<String> = spec
            .get("paths")
            .and_then(|p| p.as_object())
            .map(|o| o.keys().cloned().collect())
            .unwrap_or_default();
        v.sort();
        v
    })
}

/// Levenshtein edit distance, iterative two-row.
fn edit_distance(a: &str, b: &str) -> usize {
    let (a, b): (Vec<char>, Vec<char>) = (a.chars().collect(), b.chars().collect());
    if a.is_empty() {
        return b.len();
    }
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur = vec![0usize; b.len() + 1];
    for (i, ca) in a.iter().enumerate() {
        cur[0] = i + 1;
        for (j, cb) in b.iter().enumerate() {
            let sub = prev[j] + usize::from(ca != cb);
            cur[j + 1] = sub.min(prev[j + 1] + 1).min(cur[j] + 1);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

/// The documented paths closest to `path`, nearest first, at most three.
///
/// Measured motivation: an agent with full source access still guessed
/// `/v1/memory_token_resolve` for `/v1/memory_token/resolve` and a bare
/// `/<fact_cid>` for `/v1/facts/{cid}`. Both are one cheap edit away from the
/// real route, and answering "did you mean" costs one pass over ~113 strings
/// on a path that was already going to 404.
fn suggest_paths(path: &str) -> Vec<String> {
    // A bare 32-byte digest is the single most likely near miss: it is what a
    // content-addressed store invites you to paste after the domain.
    if let Some(seg) = path.strip_prefix('/') {
        if !seg.contains('/') && looks_like_cid(seg) {
            return vec![format!("/v1/facts/{seg}")];
        }
    }
    // Tolerate roughly a quarter of the path being wrong, so a genuine typo is
    // caught while an unrelated path suggests nothing rather than noise.
    let budget = (path.len() / 4).max(2);
    let mut scored: Vec<(usize, &String)> = documented_paths()
        .iter()
        .map(|p| (edit_distance(path, p), p))
        .filter(|(d, _)| *d <= budget)
        .collect();
    scored.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(b.1)));
    scored.into_iter().take(3).map(|(_, p)| p.clone()).collect()
}

/// The methods a documented path accepts, read from the OpenAPI spec.
///
/// The spec is already the canonical route list and is reconciled by
/// `scripts/sync_counts.py`, so reading it here means there is no second table
/// to drift out of step with the router.
fn methods_for_path(path: &str) -> Vec<String> {
    const VERBS: [&str; 7] = ["get", "post", "put", "patch", "delete", "head", "options"];
    let spec = openapi_spec();
    let item = spec.get("paths").and_then(|p| p.get(path));
    // A concrete path like /v1/a2a/tasks/abc is documented as /v1/a2a/tasks/{id};
    // match those by shape so a templated route still reports its methods.
    let item = item.or_else(|| {
        let want: Vec<&str> = path.trim_matches('/').split('/').collect();
        spec.get("paths").and_then(|p| p.as_object()).and_then(|o| {
            o.iter().find_map(|(k, v)| {
                let have: Vec<&str> = k.trim_matches('/').split('/').collect();
                (have.len() == want.len()
                    && have
                        .iter()
                        .zip(&want)
                        .all(|(h, w)| h.starts_with('{') || h == w))
                .then_some(v)
            })
        })
    });
    item.and_then(|i| i.as_object())
        .map(|o| {
            VERBS
                .iter()
                .filter(|v| o.contains_key(**v))
                .map(|v| v.to_uppercase())
                .collect()
        })
        .unwrap_or_default()
}

/// What a request to a wired path with the wrong method gets.
///
/// axum answers an unmatched method with a bare 405 and no body. That is a dead
/// end everywhere, and it became a visible one when the ChatGPT listing sent
/// people to `GET /v1/verify_receipt`: 74 of the 78 POST-only paths returned
/// 405 with zero bytes, so the reader learned neither that the path exists nor
/// how to call it. Every other error this API serves is typed and names the
/// accepted alternative; this one contradicted that promise at exactly the
/// moment a newcomer arrives.
///
/// It answers with the same `emem.error.v1` envelope, an `Allow` header so
/// ordinary HTTP tooling can act on it, and a worked call. Browsers get a short
/// HTML page rather than JSON, because the reader who hit this from a link is a
/// person, not an agent.
async fn serve_405(req: axum::http::Request<axum::body::Body>) -> Response {
    let path = req.uri().path().to_string();
    let tried = req.method().as_str().to_string();
    let origin_header = req
        .headers()
        .get("origin")
        .and_then(|v| v.to_str().ok())
        .map(|s| s.to_string());

    // OPTIONS is never "method not allowed": it is how a browser asks whether
    // it may make the real request. This fallback is registered after the CORS
    // layer and so is not wrapped by it, so a preflight landing here was
    // answered 405 with no allow-origin header, and claude.ai preflights /mcp
    // before it will connect. Answer it the way the layer would have.
    if req.method() == Method::OPTIONS {
        let mut resp = Response::builder()
            .status(StatusCode::NO_CONTENT)
            .body(axum::body::Body::empty())
            .unwrap_or_else(|_| StatusCode::NO_CONTENT.into_response());
        apply_cors_headers(&mut resp, origin_header.as_deref());
        return resp;
    }
    let allowed = methods_for_path(&path);
    let allow_hdr = if allowed.is_empty() {
        "POST".to_string()
    } else {
        allowed.join(", ")
    };
    let primary = allowed
        .iter()
        .find(|m| *m != "GET" && *m != "HEAD" && *m != "OPTIONS")
        .cloned()
        .unwrap_or_else(|| "POST".to_string());
    let origin = public_origin().unwrap_or_else(|| "https://emem.dev".into());
    let example = format!(
        "curl -s -X {primary} {origin}{path} -H 'content-type: application/json' -d '{{...}}'"
    );

    let accept = req
        .headers()
        .get(axum::http::header::ACCEPT)
        .and_then(|v| v.to_str().ok())
        .unwrap_or("");
    if accept.contains("text/html") {
        let html = format!(
            "<!doctype html><meta charset=utf-8><meta name=viewport \
             content=\"width=device-width,initial-scale=1\">\
             <title>{path} needs {primary}</title>\
             <style>body{{font:16px/1.6 ui-monospace,SFMono-Regular,Menlo,monospace;\
             background:#f7f4ec;color:#2b2620;margin:0;padding:12vh 6vw;max-width:52rem}}\
             h1{{font:600 1.35rem/1.3 ui-monospace,monospace;margin:0 0 1rem}}\
             code,pre{{background:#efeadd;border:1px solid #ddd6c6;padding:.15rem .4rem}}\
             pre{{padding:.9rem;overflow-x:auto}}a{{color:#2f6b34}}</style>\
             <h1>This endpoint is real. It takes {primary}, not {tried}.</h1>\
             <p><code>{path}</code> exists and is documented; it just does not answer \
             <code>{tried}</code>.</p><pre>{example}</pre>\
             <p>The request shape is in <a href=\"/openapi.json\">/openapi.json</a>. \
             To check a receipt by hand there is a page for it at \
             <a href=\"/verify\">/verify</a>, and the full endpoint list is at \
             <a href=\"/reference\">/reference</a>.</p>"
        );
        let mut resp = Response::builder()
            .status(StatusCode::METHOD_NOT_ALLOWED)
            .header(CONTENT_TYPE, "text/html; charset=utf-8")
            .body(axum::body::Body::from(html))
            .unwrap_or_else(|_| StatusCode::INTERNAL_SERVER_ERROR.into_response());
        resp.headers_mut().insert(
            axum::http::header::ALLOW,
            axum::http::HeaderValue::from_str(&allow_hdr)
                .unwrap_or(axum::http::HeaderValue::from_static("POST")),
        );
        apply_cors_headers(&mut resp, origin_header.as_deref());
        return resp;
    }

    let body = json!({
        "schema":  "emem.error.v1",
        "code":    "method_not_allowed",
        "message": format!(
            "{path} is a wired endpoint but does not answer {tried}. It accepts {allow_hdr}. \
             This is not a missing route: call it with {primary} and the request shape from \
             GET /openapi.json."),
        "path":    path,
        "method_tried": tried,
        "allow":   allowed,
        "example": example,
        "openapi": format!("{origin}/openapi.json"),
    });
    let mut resp = (StatusCode::METHOD_NOT_ALLOWED, Json(body)).into_response();
    resp.headers_mut().insert(
        axum::http::header::ALLOW,
        axum::http::HeaderValue::from_str(&allow_hdr)
            .unwrap_or(axum::http::HeaderValue::from_static("POST")),
    );
    apply_cors_headers(&mut resp, origin_header.as_deref());
    resp
}

async fn serve_404(req: axum::http::Request<axum::body::Body>) -> Response {
    let accept = req
        .headers()
        .get(axum::http::header::ACCEPT)
        .and_then(|v| v.to_str().ok())
        .unwrap_or("");
    let prefers_html = accept.contains("text/html") || accept.is_empty();
    if prefers_html {
        let mut resp = text_response("text/html; charset=utf-8", NOT_FOUND_HTML);
        *resp.status_mut() = StatusCode::NOT_FOUND;
        return resp;
    }
    let path = req.uri().path();
    let suggestions = suggest_paths(path);
    // Say only what was actually done. The previous wording claimed no "fact
    // CID matched", which this handler never checked: a live cid pasted bare
    // returned a 404 asserting it did not exist, which reads as a dangling
    // reference rather than a wrong route.
    let message = if suggestions.is_empty() {
        format!(
            "no route matched {path}. Call GET /openapi.json for the wired \
             endpoints, or open the 404 HTML view with `Accept: text/html` for \
             the canonical landing."
        )
    } else {
        format!(
            "no route matched {path}. Did you mean {}? A fact CID is not \
             addressable at the domain root: resolve one at /v1/facts/{{cid}}. \
             Call GET /openapi.json for the full list of wired endpoints.",
            suggestions.join(" or ")
        )
    };
    let body = json!({
        "schema":  "emem.error.v1",
        "code":    "not_found",
        "message": message,
        "path":    path,
        "did_you_mean": suggestions,
    });
    (StatusCode::NOT_FOUND, Json(body)).into_response()
}

