/// Build a [security.txt](https://datatracker.ietf.org/doc/html/rfc9116) body
/// from environment configuration. Operators set:
///
/// - `EMEM_TLS_CONTACT`, `mailto:` or `https:` URI for security reports.
/// - `EMEM_PUBLIC_URL`, origin for the `Canonical:` field (e.g.
///   `https://emem.dev`); falls back to the first domain in
///   `EMEM_TLS_DOMAINS`. If neither is set, `Canonical:` is omitted.
/// - `EMEM_SECURITY_POLICY_URL`, optional URL for `Policy:`.
///
/// `Expires:` is computed at render time as now + 365d (RFC 9116 recommends
/// ≤1 year), so a long-running responder never serves a stale expiry.
fn build_security_txt() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let mut out = String::new();
    if let Ok(contact) = std::env::var("EMEM_TLS_CONTACT") {
        let c = contact.trim();
        if !c.is_empty() {
            out.push_str("Contact: ");
            out.push_str(c);
            out.push('\n');
        }
    }
    // Always advertise the GitHub Security Advisory pathway as a
    // second Contact, that's where the open-source coordinated-disclosure
    // workflow actually lives. Operators running a fork can override
    // the repo via EMEM_SECURITY_ADVISORIES_URL.
    let advisories_url = std::env::var("EMEM_SECURITY_ADVISORIES_URL")
        .unwrap_or_else(|_| "https://github.com/Vortx-AI/emem/security/advisories/new".to_string());
    out.push_str("Contact: ");
    out.push_str(&advisories_url);
    out.push('\n');
    if let Some(origin) = public_origin() {
        out.push_str("Canonical: ");
        out.push_str(&origin);
        out.push_str("/.well-known/security.txt\n");
        // No `Encryption:` field. RFC 9116 §2.5.4 requires it to point at
        // an encryption key, and the only key this responder publishes is
        // the ed25519 signing key at /.well-known/emem.json. ed25519 is a
        // signature scheme: you cannot encrypt to it. This field used to
        // name that URL, which offered reporters an affordance that does
        // not exist. A reporter who believes they encrypted a finding and
        // did not is worse off than one who was never offered the option,
        // so the field is omitted until there is a real age/PGP key to
        // publish. /.well-known/emem.json is still the way to confirm you
        // are talking to this responder, which is a different job.
    }
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
        + 365 * 24 * 60 * 60;
    out.push_str(&format!("Expires: {}\n", iso8601_utc(secs)));
    out.push_str("Preferred-Languages: en\n");
    if let Ok(policy) = std::env::var("EMEM_SECURITY_POLICY_URL") {
        let p = policy.trim();
        if !p.is_empty() {
            out.push_str("Policy: ");
            out.push_str(p);
            out.push('\n');
        }
    } else if advisories_url.contains("github.com/Vortx-AI/emem") {
        out.push_str("Policy: https://github.com/Vortx-AI/emem/blob/main/SECURITY.md\n");
    }
    out.push_str("Acknowledgments: ");
    out.push_str(advisories_url.trim_end_matches("/new"));
    out.push('\n');
    out.push_str("\n# Scope: emem.dev REST + MCP surface, signed-receipt verification path,\n");
    out.push_str("# attestation log, and the source repo. Third-party open-data providers\n");
    out.push_str("# (Sentinel/MODIS/STAC/etc.) are out of scope, report those upstream.\n");
    out
}

/// Returns the configured public origin (no trailing slash), or `None` if
/// neither `EMEM_PUBLIC_URL` nor `EMEM_TLS_DOMAINS` is set.
fn public_origin() -> Option<String> {
    if let Ok(u) = std::env::var("EMEM_PUBLIC_URL") {
        let u = u.trim().trim_end_matches('/');
        if !u.is_empty() {
            return Some(u.to_string());
        }
    }
    if let Ok(domains) = std::env::var("EMEM_TLS_DOMAINS") {
        let first = domains.split(',').next().unwrap_or("").trim();
        if !first.is_empty() {
            return Some(format!("https://{first}"));
        }
    }
    None
}

/// BLAKE3 hex digest of the running executable. Computed once at first
/// call by reading `/proc/self/exe` (Linux) or `std::env::current_exe()`
/// (everywhere else); cached for the lifetime of the process. Used by
/// the operator-attestation field of `/.well-known/emem.json` to bind
/// the running binary to a verifiable hash. Returns the literal
/// `"unreadable"` if the executable path resolves but the read fails
/// (sandboxed environment, deleted-and-replaced binary, etc.); the
/// honest absence is published rather than a fabricated value.
fn binary_blake3_hex() -> &'static str {
    static CACHE: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    CACHE
        .get_or_init(|| {
            let path = match std::env::current_exe() {
                Ok(p) => p,
                Err(_) => return "unknown".to_string(),
            };
            match std::fs::read(&path) {
                Ok(bytes) => blake3::hash(&bytes).to_hex().to_string(),
                Err(_) => "unreadable".to_string(),
            }
        })
        .as_str()
}

/// Render `secs` (Unix epoch seconds) as RFC 3339 / ISO 8601 UTC.
fn iso8601_utc(secs: u64) -> String {
    // Days since epoch + civil-from-days (Howard Hinnant), avoids pulling chrono
    // for one timestamp formatter.
    let days = (secs / 86_400) as i64;
    let sod = (secs % 86_400) as u32;
    let (y, m, d) = civil_from_days(days);
    let hh = sod / 3600;
    let mm = (sod / 60) % 60;
    let ss = sod % 60;
    format!("{y:04}-{m:02}-{d:02}T{hh:02}:{mm:02}:{ss:02}Z")
}

/// Convert civil (Y, M, D) → days since 1970-01-01 (the inverse of
/// `civil_from_days`). Same Hinnant reference; works for any year in the
/// proleptic Gregorian calendar without pulling chrono.
pub(crate) fn days_from_civil(y: i32, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y } as i64;
    let m = m as i64;
    let d = d as i64;
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = if m > 2 { m - 3 } else { m + 9 };
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146_097 + doe - 719_468
}

/// Unix epoch seconds for `YYYY-01-01T00:00:00Z`. Used as the canonical
/// per-year anchor for annual-snapshot bands like Tessera.
fn jan1_unix(year: i32) -> i64 {
    days_from_civil(year, 1, 1) * 86_400
}

/// Build a `tslot` for a fact whose observation time is known in unix
/// seconds. Looks up the band's tempo from the registry; falls back to
/// `Tempo::Slow` (yearly) when the band isn't declared, every site
/// currently wired here is at most yearly so the fallback is honest.
///
/// **Why this exists.** The 2026-05-29 audit caught 7 materializers
/// persisting facts with `tslot: 0` despite having the
/// year-or-daily-date already in scope. Bi-temporal recall
/// (`as_of_tslot < observation`) silently matched the wrong vintage
/// because `0 <= any_bound` always passes. Threading the tempo here
/// makes every fact's `tslot` reflect the real observation time.
fn tslot_at_band(unix_seconds: i64, band: &str) -> u64 {
    let tempo = band_tempo_for_key(band).unwrap_or(emem_core::tslot::Tempo::Slow);
    emem_core::tslot::Tslot::from_unix(unix_seconds, tempo).0
}

/// Convenience: per-band tslot anchored at `YYYY-01-01T00:00:00Z`.
fn tslot_for_year(year: i32, band: &str) -> u64 {
    tslot_at_band(jan1_unix(year), band)
}

/// Parse an Overture release string like `"2025-04-23.0"` into the unix
/// seconds at midnight UTC of that date. Releases ship monthly; the
/// `.N` suffix is a minor revision pin and doesn't change the calendar
/// date. Returns `None` if the input doesn't begin with `YYYY-MM-DD`.
fn overture_release_unix(release: &str) -> Option<i64> {
    let head = release.split('.').next()?;
    let mut parts = head.split('-');
    let y: i32 = parts.next()?.parse().ok()?;
    let m: u32 = parts.next()?.parse().ok()?;
    let d: u32 = parts.next()?.parse().ok()?;
    Some(days_from_civil(y, m, d) * 86_400)
}

/// RADD alert date in `YYYYDDD` format (4-digit year + 3-digit Julian
/// day-of-year, 1-based) → unix seconds at midnight UTC of that day.
/// Used by `materialize_radd_band` so RADD's daily alerts persist with
/// a real tslot instead of 0.
fn radd_yyyyddd_to_unix(yyyyddd: u32) -> i64 {
    let y = (yyyyddd / 1000) as i32;
    let doy = (yyyyddd % 1000).max(1);
    let jan1 = jan1_unix(y);
    jan1 + (doy.saturating_sub(1) as i64) * 86_400
}

/// Convert days since 1970-01-01 to civil (Y, M, D). Algorithm by Howard
/// Hinnant, overflow-safe for any plausible epoch second.
fn civil_from_days(z: i64) -> (i32, u32, u32) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = (z - era * 146_097) as u64;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    let y = if m <= 2 { y + 1 } else { y };
    (y as i32, m, d)
}
