/// `GET /gemini-extension.json`, Gemini CLI extension manifest rendered
/// at request time from the live registry counts so the wire response
/// cannot disagree with `/mcp tools/list`. The static file at
/// `examples/gemini-extension.json` is the in-repo template; the
/// rendered manifest pulls counts from `emem_mcp::TOOLS`,
/// `emem_core::bands::DEFAULT`, and `emem_core::algorithms::DEFAULT`.
async fn serve_example_gemini() -> Response {
    let n_tools = emem_mcp::TOOLS.len();
    let n_bands = emem_core::bands::DEFAULT.bands.len();
    let n_algorithms = emem_core::algorithms::DEFAULT.algorithms.len();
    let manifest = json!({
        "_doc": format!(
            "Gemini CLI extension manifest. Install with one command: `gemini extensions install https://emem.dev/gemini-extension.json`. After install, every Gemini CLI session can call emem_recall, emem_compare, emem_find_similar, emem_memory_bundle, emem_memory_contradictions, etc. against any place on Earth without an API key. The hosted instance at https://emem.dev/mcp is HTTPS-only Streamable HTTP transport (MCP 2025-03-26+). For self-hosted, change `url` to your own emem responder. Counts ({}/{}/{}) are rendered from the live registry at request time.",
            n_tools, n_bands, n_algorithms,
        ),
        "name": "emem",
        "version": env!("CARGO_PKG_VERSION"),
        "description": format!(
            "Shared, verifiable memory for AI agents that stops referential drift, the paraphrase side pinned by the token, the world-readout side reported by the change-attribution ledger (the numeric split is roadmap): one canonical, citeable identity per place, fact, and object (emem:entity:<entity_cid>), so different models reason from the same world object. Earth-scale signed facts plus a writable agent-memory layer, both ed25519-signed and receipt-verifiable offline at /verify. {n_tools} MCP tools, {n_bands} bands, {n_algorithms} composition algorithms. Bi-temporal recall (as_of_tslot + as_of_signed_at), CoALA-typed memory files, capability-bound writes, signed bundles (emem:bundle:<bundle_cid>), multi-attester contradiction scoring. No API keys."
        ),
        "author": "Vortx AI Private Limited <avijeet@vortx.ai>",
        "license": "Apache-2.0",
        "homepage": "https://emem.dev",
        "repository": "https://github.com/Vortx-AI/emem",
        "documentation": "https://emem.dev/agents.md",
        "icon": "https://emem.dev/logo.png",
        "keywords": [
            "memory",
            "agent-memory",
            "verifiable",
            "identity",
            "mcp",
            "ed25519",
            "content-addressed",
            "earth-observation",
            "satellite",
            "no-api-key"
        ],
        "mcpServers": {
            "emem": {
                "url": "https://emem.dev/mcp",
                "transport": "streamable-http",
                "description": "Shared, verifiable memory for AI agents: recall signed facts, cite them as emem: tokens, verify receipts offline; compare, diff, and trajectory read the same memory."
            }
        },
        "context": {
            "agent_card_url": "https://emem.dev/v1/agent_card",
            "openapi_url": "https://emem.dev/openapi.json",
            "llms_txt_url": "https://emem.dev/llms.txt",
            "llms_full_txt_url": "https://emem.dev/llms-full.txt",
            "well_known_url": "https://emem.dev/.well-known/emem.json",
            "agent_card_a2a_url": "https://emem.dev/.well-known/agent-card.json",
            "gallery_url": "https://emem.dev/docs/gallery",
            "diagrams_url": "https://emem.dev/docs/diagrams/"
        },
        "live_counts": {
            "mcp_tools":  n_tools,
            "bands":      n_bands,
            "algorithms": n_algorithms,
            "rendered_at_unix_s": now_unix_s(),
        },
        "examples": [
            {
                "name": "Locate a place by name",
                "tool": "emem_locate",
                "arguments": { "q": "Mount Fuji" }
            },
            {
                "name": "Recall elevation at a cell",
                "tool": "emem_recall",
                "arguments": { "cell": "damO.zb000.xUti.zde78", "bands": ["copdem30m.elevation_mean"] }
            },
            {
                "name": "Find similar places",
                "tool": "emem_find_similar",
                "arguments": { "key": "damO.zb000.xUti.zde78", "band": "geotessera", "k": 5 }
            }
        ]
    });
    let body = serde_json::to_vec_pretty(&manifest).unwrap_or_default();
    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json; charset=utf-8")
        .body(axum::body::Body::from(body))
        .unwrap_or_else(|_| StatusCode::INTERNAL_SERVER_ERROR.into_response())
}
