/// `GET /agents.txt`, robots.txt-style plaintext discovery card.
/// One line per canonical agent-facing surface. Directory crawlers
/// (AgenstryBot, MCP-Catalog-Bot) model discovery after `/robots.txt`
/// and find emem here in a single fetch. All URLs are agent-readable
/// and self-describing; an LLM that lands here knows where to go next
/// without rendering HTML.
async fn serve_agents_txt() -> Response {
    let origin = public_origin().unwrap_or_else(|| "https://emem.dev".into());
    let body = format!(
        "# {origin}, shared verifiable memory for AI agents.\n\
         # Plaintext discovery card. One line per canonical agent surface.\n\
         # Source: github.com/Vortx-AI/emem (Apache-2.0).\n\
         \n\
         Agent-Card: {origin}/.well-known/agent-card.json\n\
         MCP: {origin}/mcp\n\
         MCP-Card: {origin}/.well-known/mcp/server-card.json\n\
         OpenAPI: {origin}/openapi.json\n\
         LLMs-Txt: {origin}/llms.txt\n\
         LLMs-Full-Txt: {origin}/llms-full.txt\n\
         Agents-Md: {origin}/agents.md\n\
         Spec: {origin}/spec.md\n\
         Memory-Model: {origin}/docs/model.html\n\
         Benchmarks: {origin}/docs/benchmarks.html\n\
         Whitepaper: {origin}/whitepaper.md\n\
         Discover: {origin}/v1/agent_card\n\
         Tools: {origin}/v1/tools\n\
         Algorithms: {origin}/v1/algorithms\n\
         Manifests: {origin}/v1/manifests\n\
         Stream: {origin}/v1/stream\n\
         Coverage: {origin}/v1/coverage_map.svg\n\
         Verify: {origin}/verify\n\
         Operator-Attestation: {origin}/.well-known/emem.json\n\
         Repository: https://github.com/Vortx-AI/emem\n\
         License: Apache-2.0\n\
         Contact: avijeet@vortx.ai\n\
         Auth: none (reads); ed25519-signed responses; offline-verifiable\n\
         Allow: *\n\
         Disallow:\n"
    );
    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "text/plain; charset=utf-8")
        .header(CACHE_CONTROL, "public, max-age=86400")
        .body(axum::body::Body::from(body))
        .unwrap_or_else(|_| StatusCode::INTERNAL_SERVER_ERROR.into_response())
}

/// `GET /v1/deprecations`, empty list with the deprecation policy.
/// ClaudeBot polls this; returning a typed stable list (instead of
/// 404) tells a crawler the surface exists and is intentionally empty.
async fn serve_deprecations() -> Json<JsonValue> {
    Json(json!({
        "schema":     "emem.deprecations.v1",
        "deprecated": [],
        "policy":     "Pre-1.0. A breaking change carries a deprecation entry here one minor release before removal. Entries name the path, the replacement, and the earliest version that removes the old surface.",
        "spec":       "https://emem.dev/spec.md",
        "served_at":  iso8601_utc(now_unix_s() as u64),
    }))
}

/// `GET /v1/models` and `GET|POST /v1/chat/completions`, agents
/// probing for the OpenAI-API shape land here. Return a typed 404
/// pointing them at `/v1/ask` (the closest emem equivalent: a
/// place-anchored Q&A with a signed receipt) and `/v1/algorithms`
/// (the equivalent of a "model catalog" on this surface).
async fn not_an_llm_provider() -> Response {
    let origin = public_origin().unwrap_or_else(|| "https://emem.dev".into());
    let body = json!({
        "schema":  "emem.error.v1",
        "code":    "not_found",
        "message": "emem is not an LLM provider; there is no chat/completions or model-list endpoint. The closest emem equivalents are POST /v1/ask (a place-anchored question with a signed answer) and GET /v1/algorithms (the catalog of named composition recipes).",
        "details": {
            "ask":        format!("POST {origin}/v1/ask   body: {{q, place|cell|lat+lng}}"),
            "algorithms": format!("GET  {origin}/v1/algorithms?summary=true"),
            "tools":      format!("GET  {origin}/v1/tools"),
            "agent_card": format!("GET  {origin}/.well-known/agent-card.json"),
            "spec":       format!("GET  {origin}/spec.md"),
        }
    });
    (StatusCode::NOT_FOUND, Json(body)).into_response()
}

/// `GET /v1/algorithm_cids`, list-form alias for the algorithms hash
/// surfaced under `/v1/manifests`. Some agents reach here first when
/// asked to "pin the algorithm registry"; mirror the relevant fields
/// so they don't bounce through two URLs.
async fn serve_algorithm_cids() -> Json<JsonValue> {
    let algos = &emem_core::algorithms::DEFAULT;
    Json(json!({
        "schema":         "emem.algorithm_cids.v1",
        "algorithms_cid": ALGORITHMS_CID.clone(),
        "n_algorithms":   algos.algorithms.len(),
        "manifests":      "/v1/manifests",
        "algorithms":     "/v1/algorithms?summary=true",
        "per_algorithm":  "/v1/algorithms/<key>",
        "served_at":      iso8601_utc(now_unix_s() as u64),
    }))
}

// ── Introspection routes ─────────────────────────────────────────────────

/// Dead-cheap liveness probe. Returns process identity and uptime WITHOUT
/// touching sled, the GPU, or any shared lock, so it answers in microseconds
/// even while a cold bake or a deploy has the index-scan path (used by
/// `/health`) contended. This is the surface to poll during a deploy window:
/// a 200 means the process is up and serving. The navigatable_worlds/eudr
/// agents reported whole-responder read timeouts during deploys precisely
/// because the only status surface (`/health`) does a 32K-row index scan;
/// this one does not.
async fn liveness(State(s): State<AppState>) -> Json<JsonValue> {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    Json(json!({
        "ok": true,
        "name": "emem",
        "version": env!("CARGO_PKG_VERSION"),
        "responder_pubkey_b32": data_encoding::BASE32_NOPAD
            .encode(&s.identity.pubkey.0)
            .to_lowercase(),
        "responder_key_epoch": s.identity.epoch.0,
        "started_at_unix_s": s.started_at_unix_s,
        "now_unix_s": now,
        "uptime_seconds": (now - s.started_at_unix_s).max(0),
        "probe": "liveness",
        "note": "Dead-cheap: no storage scan, safe to poll during a deploy or cold bake. GET /health additionally reports corpus stats and can be slower under load.",
    }))
}

async fn health(State(s): State<AppState>) -> Json<JsonValue> {
    // Cheap runtime stats, agents check this before relying on cache
    // hit rates or recently-attested facts. Distinct bands / total
    // facts come from one storage.scan_index pass capped at the same
    // limit coverage_matrix uses, so the call stays bounded even on a
    // large corpus.
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let uptime_s = (now - s.started_at_unix_s).max(0);
    let limit: usize = 32_768;
    let mut total_facts: u64 = 0;
    let mut distinct_cells = std::collections::HashSet::<String>::new();
    let mut distinct_bands = std::collections::HashSet::<String>::new();
    if let Ok(rows) = s.storage.iter_index(Some(limit)).await {
        for (k, _) in &rows {
            total_facts += 1;
            distinct_cells.insert(k.cell.clone());
            distinct_bands.insert(k.band.clone());
        }
    }
    Json(json!({
        "ok": true,
        "name": "emem",
        "version": env!("CARGO_PKG_VERSION"),
        "responder_pubkey_b32": data_encoding::BASE32_NOPAD
            .encode(&s.identity.pubkey.0)
            .to_lowercase(),
        "responder_key_epoch": s.identity.epoch.0,
        "registry_cid": s.manifests.registry_cid.as_str(),
        "schema_cid": s.manifests.schema_cid.as_str(),
        "bands_cid": &s.manifests.bands_cid,
        "sources_cid": &s.manifests.sources_cid,
        "algorithms_cid": ALGORITHMS_CID.clone(),
        "started_at_unix_s": s.started_at_unix_s,
        "now_unix_s": now,
        "uptime_seconds": uptime_s,
        "corpus": {
            "facts_scanned": total_facts,
            "distinct_cells": distinct_cells.len(),
            "distinct_bands": distinct_bands.len(),
            "scan_index_limit": limit,
            "note": "facts_scanned reflects the index scan cap; corpora above the cap are paginated via /v1/coverage_matrix",
        },
    }))
}

/// Domain separator for the operator-attestation preimage.
const OPERATOR_ATTESTATION_DOMAIN: &str = "emem.operator_attestation.v1";

/// Segment tags for the operator-attestation preimage. Stable wire
/// constants, never renumber.
mod operator_attestation_tag {
    pub const VERSION: u8 = 1;
    pub const KEY_EPOCH: u8 = 2;
    pub const ATTESTED_AT: u8 = 3;
    pub const GIT_COMMIT: u8 = 4;
    pub const BUILD_TIMESTAMP: u8 = 5;
    pub const BINARY_BLAKE3: u8 = 6;
    pub const BANDS_CID: u8 = 7;
    pub const REGISTRY_CID: u8 = 8;
}

async fn well_known(State(s): State<AppState>) -> Response {
    // Operator attestation: a signed liveness claim binding the running
    // binary's provenance (git commit, build timestamp, BLAKE3 hash of
    // the on-disk executable) plus the protocol state (version, key
    // epoch, manifest CIDs, served_at) under the responder's Ed25519
    // key. A verifier reconstructs `preimage` from the named fields and
    // checks the signature against `responder.pubkey_b32`. The chain is
    // operator-grade, not yet TEE-grade: a full Intel SGX / AMD SEV-SNP
    // attestation report (`tee_quote`) is deployment infrastructure and
    // ships as `null` from this responder until that infra lands;
    // whitepaper §20 holds the path.
    let version = env!("CARGO_PKG_VERSION");
    let git_commit = option_env!("EMEM_GIT_COMMIT").unwrap_or("unknown");
    let build_timestamp = option_env!("EMEM_BUILD_TIMESTAMP").unwrap_or("unknown");
    let binary_blake3 = binary_blake3_hex();
    let attested_at = {
        let secs = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);
        iso8601_utc(secs)
    };
    let pubkey_b32 = data_encoding::BASE32_NOPAD
        .encode(&s.identity.pubkey.0)
        .to_lowercase();
    let bands_cid: &str = s.manifests.bands_cid.as_ref();
    let registry_cid: &str = s.manifests.registry_cid.as_str();
    // Tagged, length-prefixed v1 preimage. Was a raw pipe-delimited UTF-8
    // string signed directly; that construction was the only signed family
    // outside the PreimageV1 rule, had no verifier in-tree, and its
    // unescaped `|` separators made two different field sets able to render
    // the same bytes. Signing blake3 of a domain-separated tagged stream is
    // now the invariant across every signed object; the segment table is
    // published at GET /v1/verifier_spec.
    let mut pb = emem_attest::PreimageV1::new(OPERATOR_ATTESTATION_DOMAIN);
    pb.seg(operator_attestation_tag::VERSION, version.as_bytes());
    pb.seg(
        operator_attestation_tag::KEY_EPOCH,
        &s.identity.epoch.0.to_be_bytes(),
    );
    pb.seg(
        operator_attestation_tag::ATTESTED_AT,
        attested_at.as_bytes(),
    );
    pb.seg(operator_attestation_tag::GIT_COMMIT, git_commit.as_bytes());
    pb.seg(
        operator_attestation_tag::BUILD_TIMESTAMP,
        build_timestamp.as_bytes(),
    );
    pb.seg(
        operator_attestation_tag::BINARY_BLAKE3,
        binary_blake3.as_bytes(),
    );
    pb.seg(operator_attestation_tag::BANDS_CID, bands_cid.as_bytes());
    pb.seg(
        operator_attestation_tag::REGISTRY_CID,
        registry_cid.as_bytes(),
    );
    let attest_digest = pb.finalize();
    let attest_sig = s.identity.signing.sign(&attest_digest).to_bytes();
    let attest_sig_b32 = data_encoding::BASE32_NOPAD
        .encode(&attest_sig)
        .to_lowercase();

    // /.well-known/emem.json is the *only* response that intentionally
    // emits `x-emem-version`, the manifest's whole purpose is
    // responder disclosure (pubkey, manifest CIDs, version). The header
    // is now stripped from the global middleware (see headers fn) so
    // auditors stop dinging us for server-version disclosure on every
    // /v1/* response, but it stays here.
    let body = Json(json!({
        "protocol": "emem",
        "version": version,
        "manifests": {
            "bands_cid": &s.manifests.bands_cid,
            "sources_cid": &s.manifests.sources_cid,
            "registry_cid": s.manifests.registry_cid.as_str(),
            "schema_cid": s.manifests.schema_cid.as_str(),
            "algorithms_cid": ALGORITHMS_CID.clone(),
            "topics_cid": TOPICS_CID.clone(),
            "substrates_cid": emem_core::manifest_cid(&*emem_core::substrates::DEFAULT).ok(),
            "device_platforms_cid": emem_core::manifest_cid(&*emem_core::device_platforms::DEFAULT).ok(),
            "trace_encodings_cid": emem_core::manifest_cid(&*emem_core::trace_encodings::DEFAULT).ok(),
        },
        "responder": {
            "pubkey_b32": pubkey_b32,
            "key_epoch": s.identity.epoch.0,
            "signature_alg": "ed25519",
            "hash_alg": "blake3",
            "cid_encoding": "base32-nopad-lowercase",
        },
        "operator_attestation": {
            "version":         version,
            "key_epoch":       s.identity.epoch.0,
            "attested_at":     attested_at,
            "git_commit":      git_commit,
            "build_timestamp": build_timestamp,
            "binary_blake3":   binary_blake3,
            "tee_quote":       JsonValue::Null,
            "preimage_version": 1,
            "preimage_domain":  OPERATOR_ATTESTATION_DOMAIN,
            "preimage":        "PreimageV1(\"emem.operator_attestation.v1\"){1:version, 2:key_epoch u32-BE, 3:attested_at, 4:git_commit, 5:build_timestamp, 6:binary_blake3, 7:bands_cid, 8:registry_cid}",
            "signature_b32":   attest_sig_b32,
            "alg":             "ed25519",
            "_note":           "Verify by rebuilding the tagged preimage from the named fields (bands_cid and registry_cid are under `manifests`) and checking ed25519 against `responder.pubkey_b32`. ed25519 signs blake3 of the domain-separated, length-prefixed segment stream, not a raw string: the machine-readable segment table is at GET /v1/verifier_spec. `binary_blake3` is the BLAKE3 hash of the running emem-server executable, computed once at startup by reading /proc/self/exe; together with `git_commit` and `build_timestamp` this binds the running code to a verifiable source tree. `tee_quote` is null on this responder (full Intel SGX / AMD SEV-SNP attestation report); operators who deploy under a TEE populate it from the platform's quoting service. Whitepaper §20 names the path.",
        },
        "tools_url": "/v1/tools",
        "openapi_url": "/openapi.json",
        "mcp_url": "/mcp",
        "agent_card_url": "/v1/agent_card",
        "agent_card_a2a_url": "/.well-known/agent-card.json",
        "mcp_descriptor_url": "/.well-known/mcp.json",
        "agents_md_url": "/agents.md",
        // The root document said where every door was and never what emem is.
        // An agent told to start here learned only that we have many URLs.
        "name": "emem",
        "description": EMEM_DESCRIPTION,
        "one_line": EMEM_LEAD,
        "llms_txt_url": "/llms.txt",
        // Read before the rest of this file. Every other key here answers
        // "where is it", which presupposes the reader already decided to use
        // emem; this one answers "is this the thing I need", including the
        // needs it says we do NOT serve.
        "intents_url": "/v1/intents",
        // The same registry shaped for a crawler that walks /.well-known/ and
        // would never think to call a /v1 path.
        "agent_intent_url": "/.well-known/agent-intent.json",
        "quickstart_url": "/v1/quickstart",
        "stream_url": "/v1/stream",
        "corpus_state_stats_url": "/v1/corpus_state_stats",
        "benchmark_url": "/v1/benchmark",
        "agents_roster_url": "/v1/agents",
        "a2a_skills_url": "/v1/a2a/skills",
        "substrates_url": "/v1/substrates",
        "device_platforms_url": "/v1/device_platforms",
        "trace_encodings_url": "/v1/trace_encodings",
        "oauth_authorization_server_url": "/.well-known/oauth-authorization-server",
        // POST-only endpoints. A bare GET on these returns 405 by design;
        // the `post:` prefix is a discoverability hint so a crawler doesn't
        // chase a GET that cannot answer.
        "state_url": "post:/v1/state",
        "state_multi_url": "post:/v1/state_multi",
        "state_diff_url": "post:/v1/state_diff",
        "memory_token_url": "post:/v1/memory_token",
        "memory_token_resolve_url": "post:/v1/memory_token/resolve",
        "benchmark_grade_url": "post:/v1/benchmark/grade",
        "ask_url": "post:/v1/ask",
        "inbox_url": "post:/v1/inbox",
        "a2a_tasks_sync_url": "post:/a2a/tasks",
        "a2a_tasks_async_url": "post:/v1/a2a/tasks",
        "trace_verify_url": "post:/v1/trace_verify",
        "trace_resolve_url": "post:/v1/trace_resolve",
        // Discovery hooks for connector-directory reviewers + offline
        // signature-verifying clients. The full text lives at /privacy,
        // /terms, /support; the canonical contact is the maintainer
        // email. `operator` carries the legal entity (Vortx AI Private
        // Limited, India); the flat `vendor`/`*_url` keys below are
        // kept as compatibility shims for tools that scrape the older
        // shape from earlier in the directory-prep work.
        "vendor": "Vortx-AI",
        "contact_email": "avijeet@vortx.ai",
        "privacy_url": "/privacy",
        "terms_url":   "/terms",
        "support_url": "/support",
        "operator": {
            "name":    "Vortx AI Private Limited",
            "country": "India",
            "url":     "https://vortx.ai",
            "contact": "avijeet@vortx.ai",
        },
        "policies": {
            "privacy_policy":   "/privacy",
            "terms_of_service": "/terms",
            "support":          "/support",
            "security":         "https://github.com/Vortx-AI/emem/blob/main/SECURITY.md",
        },
    }));
    let mut resp = body.into_response();
    resp.headers_mut()
        .insert("x-emem-version", version_header_value().clone());
    resp
}

async fn manifests(State(s): State<AppState>) -> Json<JsonValue> {
    let algorithms_cid = ALGORITHMS_CID.clone();
    let topics_cid = TOPICS_CID.clone();
    Json(json!({
        "bands_cid":     &s.manifests.bands_cid,
        // Spec name. The earlier `functions_cid` alias is kept below for
        // one release so existing clients don't break.
        "registry_cid":  s.manifests.registry_cid.as_str(),
        "functions_cid": s.manifests.registry_cid.as_str(),
        "sources_cid":   &s.manifests.sources_cid,
        "schema_cid":    s.manifests.schema_cid.as_str(),
        "algorithms_cid": algorithms_cid,
        "topics_cid":    topics_cid,
        // The substrate family: how each contributor class is admitted, the
        // device-platform whitelist, and the capture-encoding vocabulary.
        "substrates_cid": emem_core::manifest_cid(&*emem_core::substrates::DEFAULT).ok(),
        "device_platforms_cid": emem_core::manifest_cid(&*emem_core::device_platforms::DEFAULT).ok(),
        "trace_encodings_cid": emem_core::manifest_cid(&*emem_core::trace_encodings::DEFAULT).ok(),
        // How many entries each digest actually covers.
        //
        // A digest with no count is a claim nobody can check. 6nwstkhm hit
        // exactly that writing a conformance section: their paper stated how
        // many entries `algorithms_cid` covers, I read it as drift against the
        // 168 that `/v1/algorithms` reports, and neither of us could settle it,
        // because this endpoint returned the digest alone and the algorithms
        // endpoint paginates a DIFFERENT quantity (the callable surface). Their
        // words for it, and they are right: "a count nobody can verify has no
        // business in a conformance section".
        //
        // Settling it needed the source: the cid over the 168-entry registry
        // reproduces the served `algorithms_cid` byte for byte, so it covers
        // 168 and the two numbers were never different quantities. That should
        // have been one fetch rather than an argument, so now it is.
        //
        // Derived from the same registries the digests are computed over, in
        // the same request, so the count and the digest cannot disagree.
        "covers": {
            "bands": emem_core::bands::DEFAULT.bands.len(),
            "algorithms": emem_core::algorithms::DEFAULT.algorithms.len(),
            "sources": emem_core::sources::DEFAULT.sources.len(),
            "substrates": emem_core::substrates::DEFAULT.substrates.len(),
            "device_platforms": emem_core::device_platforms::DEFAULT.platforms.len(),
            "trace_encodings": emem_core::trace_encodings::DEFAULT.encodings.len(),
            "note": "Entry counts for the manifests digested above, from the same in-process registries the digests are taken over. `algorithms` here counts what `algorithms_cid` covers; `/v1/algorithms` `pagination.total` counts the callable surface, and they are the same number today. Where a count and a digest disagree, the digest is authoritative and this endpoint is the bug.",
        },
    }))
}

async fn bands(State(s): State<AppState>) -> Json<JsonValue> {
    // Hoist the registry's existing fields into the response root and
    // graft `bands_cid` next to them so an agent reading /v1/bands can
    // see the same content-address /v1/manifests publishes, without
    // having to call /v1/manifests separately.
    //
    // Per-band materializer status: declared bands without a wired
    // materializer used to be invisible from this endpoint. Inject
    // `materializer:{kind:"live"|"scalars_only"|"declared_no_connector",...}`
    // so the catalog tells the truth in one call. The kind is sourced
    // from the same `band_materializer_meta` dispatch that powers
    // /v1/recall, so it can't drift.
    let mut payload = serde_json::to_value(&*emem_core::bands::DEFAULT).unwrap_or(json!({}));
    if let Some(map) = payload.as_object_mut() {
        map.insert(
            "bands_cid".into(),
            JsonValue::String(s.manifests.bands_cid.clone()),
        );
        if let Some(arr) = map.get_mut("bands").and_then(|v| v.as_array_mut()) {
            for entry in arr.iter_mut() {
                let Some(obj) = entry.as_object_mut() else {
                    continue;
                };
                let key = obj
                    .get("key")
                    .and_then(|v| v.as_str())
                    .map(str::to_owned)
                    .unwrap_or_default();
                let status = if let Some(meta) = band_materializer_meta(&key) {
                    json!({
                        "kind": "live",
                        "tempo_seconds": meta.tempo.slot_seconds(),
                        "temporal_kind": meta.kind.as_str(),
                        "history_from_unix": meta.history_from_unix,
                        "history_to_unix": meta.history_to_unix,
                        "wire_path": meta.wire_path,
                    })
                } else if let Some(sample_scalar) = family_root_sample_scalar(&key) {
                    // Family-root key (e.g. `nightlights`, `terraclimate`,
                    // `sentinel2_raw`) has no direct materializer at the
                    // root, but a representative scalar child IS wired.
                    // Probe the dispatch with that child so we can quote
                    // its tempo / history / wire_path verbatim.
                    let child_meta = band_materializer_meta(sample_scalar);
                    json!({
                        "kind": "scalars_only",
                        "note": "Family-root cube key, recall on this exact key returns existing attestations only. Scalar children under this family (e.g. ".to_string() + sample_scalar + ") are auto-materialized; call /v1/materializers for the full per-scalar list.",
                        "sample_wired_child": sample_scalar,
                        "sample_child_wire_path": child_meta.as_ref().map(|m| m.wire_path),
                        "sample_child_temporal_kind": child_meta.as_ref().map(|m| m.kind.as_str()),
                    })
                } else {
                    json!({
                        "kind": "declared_no_connector",
                        "note": "Registered in the band catalog but no auto-materializer is wired at this responder, and no scalar child under this family is wired either. /v1/recall on this band will return only existing attestations (no upstream fetch). Genuine placeholders today: air_quality, _reserved_512, reserved.",
                    })
                };
                obj.insert("materializer".into(), status);
            }
        }
    }
    Json(payload)
}

/// Pick a representative scalar child for a cube family root, returning
/// the key the materializer dispatch knows about. Lets `/v1/bands`
/// distinguish "family root with wired children" from "true placeholder".
///
/// Sourced from `band_materializer_meta` arms, every entry below is
/// either an explicit case in that match or a prefix arm (`b.starts_with`).
/// If you wire a new family-root child, add the family here so the
/// catalog reflects it.
fn family_root_sample_scalar(family: &str) -> Option<&'static str> {
    Some(match family {
        // Prefix-matched arms in band_materializer_meta:
        "weather" => "weather.temperature_2m",
        "overture" => "overture.places_count",
        "power" => "power.solar_radiation_yearly",
        "cams" => "cams.air_quality_pm25",
        "era5" => "era5.t2m_yearly_mean",
        "marine" => "marine.wave_height",
        "terraclimate" => "terraclimate.tmax_jan_normal",
        "soilgrids" => "soilgrids.bulk_density_0_5cm",
        // s2_band_plan(*)-matched arm covers Sentinel-2 reflectance + indices:
        "sentinel2_raw" => "sentinel2.b04",
        "indices" => "indices.ndvi",
        // Specific scalar arms whose family root appears in the cube manifest:
        "dem" | "cop_dem" => "copdem30m.elevation_mean",
        "landcover" => "esa_worldcover.lc_2021",
        "surface_water" => "surface_water.recurrence",
        "nightlights" => "nightlights.dmsp_v4_2013",
        "forest_change" => "forest_change.tree_loss_y2024",
        "population" => "population", // root resolves; reachable via the live arm above
        // Native parametric arm (parses temporal_diff:<inner>:<window>):
        "temporal_diff" => "temporal_diff:geotessera:31536000",
        _ => return None,
    })
}

/// `GET /v1/materializers`, declare which bands this responder will
/// auto-materialize on a recall miss, what upstream source produces
/// the value, and what the resulting fact looks like (Primary or
/// Absence). Lets an agent discover, without trial-and-error, which
/// bands work cite-ably for any cell on Earth versus which require a
/// pre-existing attestation.
async fn materializers(
    State(s): State<AppState>,
    axum::extract::Query(q): axum::extract::Query<PageQuery>,
) -> Json<JsonValue> {
    let pubkey_b32 = data_encoding::BASE32_NOPAD
        .encode(&s.identity.pubkey.0)
        .to_lowercase();
    // Resolve the active Overture release tag once per call so the
    // three `overture.*` materializer entries below quote the currently
    // cached release in their `coverage` and `upstream_endpoint` fields
    // rather than an immutable literal baked in at compile time. On a
    // discovery failure the field reads `"unavailable"` (observably
    // distinct from a real tag), no silent stale fallback.
    let overture_release = match emem_fetch::overture::OvertureClient::shared()
        .release()
        .await
    {
        Ok(r) => r,
        Err(e) => {
            tracing::warn!(
                target: "emem_api_rest::materializers",
                "could not resolve Overture release for /v1/materializers: {e}"
            );
            "unavailable".to_string()
        }
    };
    let overture_buildings_endpoint = format!(
        "s3://overturemaps-us-west-2/release/{overture_release}/theme=buildings/type=building/"
    );
    let overture_places_endpoint =
        format!("s3://overturemaps-us-west-2/release/{overture_release}/theme=places/type=place/");
    let overture_segments_endpoint = format!(
        "s3://overturemaps-us-west-2/release/{overture_release}/theme=transportation/type=segment/"
    );
    let overture_coverage = format!(
        "global vector; Overture Maps Foundation {overture_release} release (auto-discovered, refreshed every 24h)"
    );
    let mut payload = json!({
        "schema": "emem.materializers.v1",
        "responder_pubkey_b32": pubkey_b32.clone(),
        "auto_materialize_enabled": auto_materialize_enabled(),
        "materializers": [
            {
                "band":              "modis.ndvi_mean",
                "unit":              null,
                "value_kind":        "primary",
                "coverage":          "global terrestrial; 250m native; latest valid 16-day composite within last 90 days",
                "upstream_scheme":   "ornl_modis",
                "upstream_endpoint": "https://modis.ornl.gov/rst/api/v1/MOD13Q1/subset",
                "derivation_fn_key": "modis_ornl_subset@1",
                "confidence":        0.9,
                "tempo":             "medium",
                "kernel_for_router": "heat_gaussian",
                "notes":             "MOD13Q1 16-day composite NDVI from MODIS Terra. ~10–15 s upstream latency. NDVI ∈ [-0.2, 1.0]; values <0 mean water/snow, >0.4 mean dense vegetation. Quality flag filtering uses fill_value=-3000 from the NASA QA layer."
            },
            {
                "band":              "gmrt.topobathy_mean",
                "unit":              "m",
                "value_kind":        "primary",
                "coverage":          "global; positive over land, negative over water",
                "upstream_scheme":   "gmrt",
                "upstream_endpoint": "https://www.gmrt.org/services/PointServer",
                "derivation_fn_key": "gmrt_pointserver@1",
                "confidence":        0.9,
                "notes":             "Lamont-Doherty Earth Observatory's Global Multi-Resolution Topography. Single dataset that fuses Cop-DEM, GEBCO, multibeam swaths, and high-res surveys into a globally-consistent topo-bathy raster. The right band when you need a number for any point on Earth, including ocean."
            },
            {
                "band":              "copdem30m.elevation_mean",
                "unit":              "m",
                "value_kind":        "primary_or_absence",
                "coverage":          "land surface only; AWS Open Data Cop-DEM GLO-30 publishes no tile over open ocean (responder signs Absence) and has documented gaps in some Antarctic interiors. Land cells globally.",
                "upstream_scheme":   "copernicus.dem.30m.aws",
                "upstream_endpoint": "https://copernicus-dem-30m.s3.amazonaws.com/",
                "derivation_fn_key": "copernicus_dem_30m_aws_pixel@1",
                "confidence":        0.95,
                "notes":             "Migrated 2026-05-29 from the rate-limited Open-Meteo per-point HTTPS path (`open_meteo_copdem90m@1`) to the AWS Open Data COG mirror. Polygon recalls now fire one HTTP range read per tile via `prewarm_polygon_static_cog_bands` instead of N rate-limited point queries. Use this when you specifically want a *land DEM* answer with a signed absence over water rather than topo-bathy. For most general-purpose elevation queries, prefer gmrt.topobathy_mean."
            },
            {
                "band":              "geotessera",
                "unit":              null,
                "value_kind":        "primary",
                "value_shape":       [128],
                "coverage":          "global terrestrial; 0.1° tile grid; v1 vintage 2024",
                "upstream_scheme":   "geotessera",
                "upstream_endpoint": "https://dl2.geotessera.org/v1/global_0.1_degree_representation",
                "derivation_fn_key": "geotessera_v1@2",
                "confidence":        0.85,
                "tempo":             "slow",
                "kernel_for_router": "linear_ar1",
                "fetch_strategy":    "https_range",
                "fetch_bytes_per_cell": 640,
                "notes":             "Tessera 128-D foundation embedding (Cambridge/Clay-style; quantized int8 + float32 scales). Per-cell HTTPS range reads against the public bucket, ~640 B downloaded per recall instead of the full 91 MB tile. Native CRS is per-tile UTM; we project (lat,lng) into the tile's UTM CRS (tessera_row_col) to pick the exact pixel, the @2 fn_key marks this UTM-correct mapping (@1 used a linear-in-degrees row/col that mis-sampled by ~1–2 px near tile corners). Default vintage 2024; use geotessera.YYYY for an explicit year, or geotessera.multi_year for the 8-year stack."
            },
            {
                "band":              "geotessera.multi_year",
                "unit":              null,
                "value_kind":        "primary",
                "value_shape":       [1024],
                "coverage":          "global terrestrial; 0.1° tile grid; 8-year stack 2017-2024",
                "upstream_scheme":   "geotessera",
                "upstream_endpoint": "https://dl2.geotessera.org/v1/global_0.1_degree_representation",
                "derivation_fn_key": "geotessera_multi_year@2",
                "confidence":        0.85,
                "tempo":             "slow",
                "kernel_for_router": "linear_ar1",
                "fetch_strategy":    "9x https_range (one per year)",
                "fetch_bytes_per_cell": 5760,
                "notes":             "1152-D = 128 × 9 years (2017,2018,2019,2020,2021,2022,2023,2024,2025). Years with no tile coverage at this cell get NaN-masked slices (so cosine over real dims is honest, not pulled toward zero); derivation.args.years_covered records which slices are real. NaN-aware scoring (find_similar / query_region) compares only the finite overlap. Use this for time-aware similarity search, the temporal trajectory of a place across the Tessera vintage."
            },
            {
                "band":              "geotessera.bin128",
                "unit":              "bin128_be",
                "value_kind":        "primary",
                "value_shape":       [16],
                "value_encoding":    "cbor.bytes(16)",
                "coverage":          "wherever geotessera is attested, derived locally, no extra upstream call",
                "upstream_scheme":   "geotessera",
                "upstream_endpoint": "(derived from cached geotessera int8+scale vector decoded to f32)",
                "derivation_fn_key": "turboquant_geotessera_bin128_v1@1",
                "confidence":        0.85,
                "tempo":             "slow",
                "fetch_strategy":    "derived: turboquant rotation + sign-bit pack",
                "fetch_bytes_per_cell": 16,
                "use_with":          "find_similar mode=hamming or hamming_then_rerank",
                "compression_ratio": "~8x vs geotessera int8+scale (~132 B → 16 B per cell); ~32x vs the recall-decoded f32 (512 B)",
                "scoring_throughput": "~10⁹ pairs/sec/core via XOR + popcount",
                "notes":             "Sign-bit-packed 128-bit binary embedding derived from the geotessera vector (int8 + per-pixel f32 scale upstream, decoded to f32 by recall) after a fixed random orthogonal rotation (TurboQuant, Corley, https://geospatialml.com/posts/terrabit/). Designed to feed `find_similar` as a triage layer: ~65% recall@10 on its own, matches cosine precision when used with mode=hamming_then_rerank (the responder pulls 4·k Hamming candidates, re-ranks by cosine on the underlying geotessera vector). Rotation matrix is content-addressed via derivation.args[2] so a verifier can re-derive bit-for-bit."
            },
            {
                "band":              "weather.temperature_2m",
                "unit":              "degC",
                "value_kind":        "primary",
                "coverage":          "global; 15-minute updates from blended HRRR/ICON/GFS/ECMWF",
                "upstream_scheme":   "met_no",
                "upstream_endpoint": "https://api.met.no/weatherapi/locationforecast/2.0/compact",
                "derivation_fn_key": "met_no_locationforecast_compact@1",
                "confidence":        0.85,
                "tempo":             "ultra_fast",
                "kernel_for_router": "advection_linear",
                "notes":             "Current 2-m air temperature in °C. MET Norway's locationforecast/2.0/compact requires no API key and is not per-IP rate-limited; their TOS asks only for an identifying User-Agent. The data is sat-fed (ECMWF + EUMETSAT geostationary fleet)."
            },
            {
                "band":              "weather.cloud_cover",
                "unit":              "percent",
                "value_kind":        "primary",
                "coverage":          "global; 15-minute updates",
                "upstream_scheme":   "met_no",
                "upstream_endpoint": "https://api.met.no/weatherapi/locationforecast/2.0/compact",
                "derivation_fn_key": "met_no_locationforecast_compact@1",
                "confidence":        0.80,
                "tempo":             "ultra_fast",
                "kernel_for_router": "advection_linear",
                "notes":             "Total cloud-cover percentage from the geostationary-fed NWP blend. Use alongside indices.ndvi to gate vegetation queries, high cloud_cover means the latest optical composite is likely stale."
            },
            {
                "band":              "weather.precipitation_mm",
                "unit":              "mm",
                "value_kind":        "primary",
                "coverage":          "global; 15-minute updates",
                "upstream_scheme":   "met_no",
                "upstream_endpoint": "https://api.met.no/weatherapi/locationforecast/2.0/compact",
                "derivation_fn_key": "met_no_locationforecast_compact@1",
                "confidence":        0.75,
                "tempo":             "ultra_fast",
                "kernel_for_router": "advection_linear",
                "notes":             "Liquid-equivalent precipitation in the last 15-minute window."
            },
            {
                "band":              "weather.wind_speed_10m",
                "unit":              "m/s",
                "value_kind":        "primary",
                "coverage":          "global; 15-minute updates",
                "upstream_scheme":   "met_no",
                "upstream_endpoint": "https://api.met.no/weatherapi/locationforecast/2.0/compact",
                "derivation_fn_key": "met_no_locationforecast_compact@1",
                "confidence":        0.80,
                "tempo":             "ultra_fast",
                "kernel_for_router": "advection_linear",
                "notes":             "10-m wind speed in m/s. The advection kernel matches how wind itself transports the rest of the weather state."
            },
            {
                "band":              "indices.ndvi",
                "unit":              null,
                "value_kind":        "primary",
                "coverage":          "global; Sentinel-2 L2A 10 m; 5-day revisit at the equator",
                "upstream_scheme":   "sentinel_s2_l2a",
                "upstream_endpoint": "https://earth-search.aws.element84.com/v1/search → https://sentinel-cogs.s3.us-west-2.amazonaws.com/...",
                "derivation_fn_key": "sentinel2_l2a_ndvi@1",
                "confidence":        0.92,
                "tempo":             "fast",
                "kernel_for_router": "wave_seasonal",
                "fetch_strategy":    "stac_search + https_range_cog",
                "fetch_bytes_per_cell": "~600 KB (IFD + 1 tile per band × 2 bands)",
                "notes":             "Pure-Rust COG range read against AWS Open Data sentinel-cogs bucket. STAC search picks the latest scene <40% cloud that *contains* the point (intersects: Point). Reflectance = DN × 1e-4 with no additive offset, which is correct because Element84 harmonises the L2A DN range: it removes ESA's BOA_ADD_OFFSET (−1000 DN from processing baseline 04.00, 2022-01-25) before publishing, so one scale reads the whole archive. Microsoft Planetary Computer serves ESA's DNs unaltered and would need the −1000 applied per item for baseline ≥ 04.00. The responder refuses to run this path against a non-harmonised catalogue rather than sign an offset-biased index. NDVI = (B08 − B04) / (B08 + B04). No API key. Range read uses Predictor 2 (horizontal differencing) + Deflate decompression."
            },
            {
                "band":              "sentinel1_raw",
                "unit":              "dB",
                "value_kind":        "primary",
                "coverage":          "global; Sentinel-1 RTC (Radiometrically Terrain Corrected) C-band SAR; ~10 m; 6-12-day revisit",
                "upstream_scheme":   "sentinel_s1_rtc_mpc",
                "upstream_endpoint": "https://planetarycomputer.microsoft.com/api/stac/v1/search (collection: sentinel-1-rtc) → Azure Blob COG signed with anonymous SAS",
                "derivation_fn_key": "sentinel1_rtc_vv_db@1",
                "confidence":        0.85,
                "tempo":             "fast",
                "kernel_for_router": "wave_seasonal",
                "fetch_strategy":    "stac_search + https_range_cog (Azure SAS-signed)",
                "fetch_bytes_per_cell": "~700 KB (IFD + 1 tile)",
                "notes":             "VV polarisation gamma-naught backscatter in dB (10·log₁₀ of linear power). Radar, works at night and through cloud, complements indices.ndvi for all-weather monitoring. Source: Microsoft Planetary Computer's `sentinel-1-rtc` collection, proper UTM-projected COG (the upstream Element84 `sentinel-1-grd` mirror ships SAFE-format scenes with GCP-based georeferencing the pure-Rust COG sampler can't decode). Asset URLs are anonymous Azure Blobs signed with a free SAS token cached process-wide."
            },
            {
                "band":              "surface_water.recurrence",
                "unit":              "percent",
                "value_kind":        "primary_or_absence",
                "value_shape":       "scalar",
                "coverage":          "global ±60° lat from JRC observation footprint; 30 m native; static climatology over 1984-2021. Absence over permanent non-water and unmapped polar interiors (255 nodata).",
                "upstream_scheme":   "jrc.gsw.v1_4.recurrence",
                "upstream_endpoint": "https://storage.googleapis.com/global-surface-water/downloads2021/recurrence/recurrence_{lon_left10}_{lat_top10}v1_4_2021.tif",
                "derivation_fn_key": "jrc_gsw_recurrence_pixel@1",
                "confidence":        0.95,
                "tempo":             "static",
                "kernel_for_router": "linear_ar1",
                "fetch_strategy":    "https_range_cog",
                "fetch_bytes_per_cell": "~320 KB (IFD head + 1 tile)",
                "notes":             "Inter-annual water recurrence in percent: 0 = never water, 100 = water every year of the 1984-2021 record, intermediate = flood-prone or seasonal water. The canonical signed answer to 'has this place been wet historically?' Pure-Rust COG range read against the public GCS bucket; tiles are EPSG:4326 so no UTM projection step. License: JRC open."
            },
            {
                "band":              "overture.buildings.count",
                "unit":              null,
                "value_kind":        "primary",
                "coverage":          overture_coverage,
                "upstream_scheme":   "overture.maps.foundation.v1",
                "upstream_endpoint": overture_buildings_endpoint,
                "active_release":    overture_release,
                "derivation_fn_key": "overture_buildings_count@1",
                "confidence":        0.95,
                "tempo":             "slow",
                "kernel_for_router": "linear_ar1",
                "fetch_strategy":    "anonymous_s3 + parquet_row_group_pruning + wkb_polygon_centroid",
                "notes":             "Count of building footprints whose vertex-mean centroid falls inside the cell bbox. Pure-Rust path: object_store anonymous AWS S3 + parquet 55 async reader + WKB decode. No GDAL, no Python, no API key. Per-file parquet footers cached in process memory; first-call to a region warms the cache. Release tag is auto-discovered from the public bucket on startup and refreshed every 24h."
            },
            {
                "band":              "overture.places.count",
                "unit":              null,
                "value_kind":        "primary",
                "coverage":          overture_coverage,
                "upstream_scheme":   "overture.maps.foundation.v1",
                "upstream_endpoint": overture_places_endpoint,
                "active_release":    overture_release,
                "derivation_fn_key": "overture_places_count@1",
                "confidence":        0.90,
                "tempo":             "slow",
                "kernel_for_router": "linear_ar1",
                "fetch_strategy":    "anonymous_s3 + parquet_row_group_pruning + wkb_point_inside",
                "notes":             "Count of POIs (places) whose Point geometry falls inside the cell bbox. Same anonymous S3 + pure-Rust parquet path as buildings."
            },
            {
                "band":              "overture.transportation.road_length_m",
                "unit":              "m",
                "value_kind":        "primary",
                "coverage":          overture_coverage,
                "upstream_scheme":   "overture.maps.foundation.v1",
                "upstream_endpoint": overture_segments_endpoint,
                "active_release":    overture_release,
                "derivation_fn_key": "overture_road_length_m@1",
                "confidence":        0.85,
                "tempo":             "slow",
                "kernel_for_router": "linear_ar1",
                "fetch_strategy":    "anonymous_s3 + parquet_row_group_pruning + wkb_linestring_clip",
                "notes":             "Sum of road-segment length (metres) intersecting the cell bbox. Each WKB LineString is clipped to the bbox via Liang-Barsky and projected planar with a local-tangent-plane scale at the cell's mid-latitude. The cell is small (~10 m × ~6 m at 52° N) so planar approximation is well within millimetres of haversine."
            }
        ],
        "agent_hint": {
            "how_it_works": "Call POST /v1/recall {cell, bands: [<band>]}. If the cell has no fact yet AND auto_materialize_enabled is true, the responder fetches the upstream value, signs the resulting fact under its identity, persists it, and returns it in the same response. The next call hits the hot cache (~10 ms instead of ~180 ms).",
            "trust_model":  "Materialized facts are signed by the responder pubkey above, NOT by the upstream provider. The fact's `derivation.fn_key` declares the function that produced the value; an external attester can run the same function and submit their own signed fact to corroborate or correct.",
            "absence_facts": "Fact::Absence (kind: \"absence\") records confirmed no-data with a content-addressed `reason_cid`. Treat it as a signed statement that the responder tried and got no answer, don't re-fetch on every call.",
            "history_bounds": "Each entry now carries `history_available_from_unix` / `history_available_to_unix` derived from the upstream provider's documented record. `null` means present-only (e.g. weather nowcast, Overture release snapshot, or static climatology). Pass these to `emem_backfill` to materialize and sign every per-tslot fact in the window, turns 'I want history' into 'history exists in the ledger'.",
        }
    });

    // Decorate every materializer entry with history bounds + a tempo
    // seconds value so an agent can size an `emem_backfill` window
    // without a second round-trip to /v1/coverage_matrix. We post-process
    // here rather than inlining per-entry to keep the inline JSON literal
    // above the single source of truth for connector text, `band_materializer_meta`
    // is the single source of truth for the bounds themselves.
    if let Some(arr) = payload
        .get_mut("materializers")
        .and_then(|v| v.as_array_mut())
    {
        for entry in arr.iter_mut() {
            let band = entry
                .get("band")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string());
            let Some(band) = band else { continue };
            let meta = band_materializer_meta(&band);
            if let Some(obj) = entry.as_object_mut() {
                obj.insert(
                    "history_available_from_unix".into(),
                    meta.as_ref()
                        .and_then(|m| m.history_from_unix)
                        .map(JsonValue::from)
                        .unwrap_or(JsonValue::Null),
                );
                obj.insert(
                    "history_available_to_unix".into(),
                    meta.as_ref()
                        .and_then(|m| m.history_to_unix)
                        .map(JsonValue::from)
                        .unwrap_or(JsonValue::Null),
                );
                if let Some(m) = meta.as_ref() {
                    obj.insert(
                        "tempo_seconds".into(),
                        JsonValue::from(m.tempo.slot_seconds()),
                    );
                    obj.insert("temporal_kind".into(), JsonValue::from(m.kind.as_str()));
                    obj.insert("upstream_wire_path".into(), JsonValue::from(m.wire_path));
                }
                obj.insert(
                    "responder_pubkey_b32".into(),
                    JsonValue::from(pubkey_b32.clone()),
                );
            }
        }
    }
    // Backfill every materializable band that the curated payload above
    // doesn't already mention, using `band_materializer_meta` +
    // `all_materializable_bands` as the registry. This guarantees the
    // /v1/materializers endpoint is never a partial view of the responder
    //, agents that introspect either /v1/materializers or
    // /v1/data_availability see the same band list. The auto-generated
    // entries have less editorial text but full machine-readable fields.
    if let Some(arr) = payload
        .get_mut("materializers")
        .and_then(|v| v.as_array_mut())
    {
        let curated: std::collections::HashSet<String> = arr
            .iter()
            .filter_map(|e| {
                e.get("band")
                    .and_then(|v| v.as_str())
                    .map(|s| s.to_string())
            })
            .collect();
        for band in all_materializable_bands() {
            if curated.contains(&band) {
                continue;
            }
            let Some(meta) = band_materializer_meta(&band) else {
                continue;
            };
            let mut obj = serde_json::Map::new();
            obj.insert("band".into(), JsonValue::from(band.clone()));
            obj.insert("value_kind".into(), JsonValue::from("primary"));
            obj.insert("auto_generated".into(), JsonValue::from(true));
            obj.insert(
                "notes".into(),
                JsonValue::from("auto-registered from band_materializer_meta, see /v1/data_availability for the full machine-readable catalog and any peer-reviewed citation in source code"),
            );
            obj.insert(
                "history_available_from_unix".into(),
                meta.history_from_unix
                    .map(JsonValue::from)
                    .unwrap_or(JsonValue::Null),
            );
            obj.insert(
                "history_available_to_unix".into(),
                meta.history_to_unix
                    .map(JsonValue::from)
                    .unwrap_or(JsonValue::Null),
            );
            obj.insert(
                "tempo_seconds".into(),
                JsonValue::from(meta.tempo.slot_seconds()),
            );
            obj.insert("temporal_kind".into(), JsonValue::from(meta.kind.as_str()));
            obj.insert("upstream_wire_path".into(), JsonValue::from(meta.wire_path));
            obj.insert(
                "responder_pubkey_b32".into(),
                JsonValue::from(pubkey_b32.clone()),
            );
            arr.push(JsonValue::Object(obj));
        }
    }

    // Pagination + summary projection. The full materializer registry was
    // ~62 KB at 0.0.4, well over MCP's 25 KB cap. Slice the array into a
    // page and (optionally) drop the long `notes` field per entry. The
    // top-level `pagination` envelope makes the slicing honest:
    // agents see `total` and `next_url` and know to iterate.
    let (page, page_size) = resolve_page_params(&q);
    let summary = q.summary.unwrap_or(false);
    let materializers_full = payload
        .as_object_mut()
        .and_then(|m| m.remove("materializers"))
        .and_then(|v| match v {
            JsonValue::Array(a) => Some(a),
            _ => None,
        })
        .unwrap_or_default();
    let total = materializers_full.len();
    let start = (page - 1).saturating_mul(page_size).min(total);
    let end = start.saturating_add(page_size).min(total);
    let items: Vec<JsonValue> = materializers_full[start..end]
        .iter()
        .map(|entry| project_materializer_entry(entry, summary))
        .collect();
    let extra = if summary { "&summary=true" } else { "" };
    let pagination = pagination_envelope(page, page_size, total, "/v1/materializers", extra);
    if let Some(map) = payload.as_object_mut() {
        map.insert(
            "_explanation".into(),
            JsonValue::from(
                "Paginated list, defaults to page=1, page_size=20 (max 100) so the response fits MCP's 25 KB cap. Pass `?page=N&page_size=K` to walk the registry, or `?summary=true` to drop the long `notes` body per entry. `pagination.total` is the full registry size, agents MUST follow `pagination.next_url` to see the rest.",
            ),
        );
        map.insert("pagination".into(), pagination);
        map.insert("items".into(), JsonValue::Array(items.clone()));
        // Back-compat alias. Older clients read the top-level
        // `materializers` key. Keep it pointing at the SAME paginated
        // slice, never the full set, so the page-size contract is
        // honoured uniformly.
        map.insert("materializers".into(), JsonValue::Array(items));
    }
    Json(payload)
}

/// Project one materializer entry. When `summary == true`, drop the
/// long `notes` field (often 1-3 paragraphs of editorial prose per
/// entry). Always retains `band`, `unit`, `value_kind`, `coverage`,
/// `upstream_scheme`, `upstream_endpoint`, `derivation_fn_key`,
/// `confidence`, `tempo`, `responder_pubkey_b32`, and the
/// `history_available_*` window so an agent can decide whether to
/// fetch the full entry from `/v1/materializers?page=…` without
/// `summary=true`.
fn project_materializer_entry(entry: &JsonValue, summary: bool) -> JsonValue {
    if !summary {
        return entry.clone();
    }
    let Some(obj) = entry.as_object() else {
        return entry.clone();
    };
    let drop_keys = ["notes"];
    let mut out = serde_json::Map::with_capacity(obj.len());
    for (k, v) in obj.iter() {
        if drop_keys.contains(&k.as_str()) {
            continue;
        }
        out.insert(k.clone(), v.clone());
    }
    out.insert("summary".into(), JsonValue::Bool(true));
    JsonValue::Object(out)
}

/// `GET /v1/data_availability`, temporal catalog: for every band this
/// responder can materialize, the upstream-of-record window the data
/// genuinely covers and the temporal shape an agent should expect from
/// `recall` / `backfill`. Driven entirely by `band_materializer_meta`
/// (single source of truth) and `all_materializable_bands` (concrete
/// enumeration including each Tessera vintage). No hardcoded windows
/// or duplicated lookups.
///
/// Shape (per entry):
/// ```json
/// {
///   "band": "geotessera.2020",
///   "kind": "annual_snapshot",
///   "tempo": "slow",
///   "tempo_seconds": 31556952,
///   "history_available_from_unix": 1577836800,
///   "history_available_to_unix":   1609459199,
///   "history_available_from_iso":  "2020-01-01T00:00:00Z",
///   "history_available_to_iso":    "2020-12-31T23:59:59Z",
///   "upstream_wire_path": "dl2.geotessera.org per-year .npy HTTPS-Range",
///   "backfill_supported": true,
///   "tslot_grid_seconds": 31556952
/// }
/// ```
///
/// `backfill_supported` is `true` iff the band has a `kind` other than
/// `now_only` AND `materialize_band_at` will accept a past `target_unix`
/// for it. Used by /v1/backfill clients to skip nowcast bands without a
/// trial-and-error 422.
#[derive(Debug, Default, Deserialize)]
struct DataAvailQuery {
    /// `compact=true` (or `projection=compact`) drops the per-band history
    /// window + upstream_wire_path, keeping `{band, kind, tempo,
    /// backfill_supported}` so the full ~122-band array survives the MCP
    /// 24 KB wire budget (reported by a consumer as an MCP truncation). REST
    /// default is full.
    #[serde(default)]
    compact: Option<bool>,
    #[serde(default)]
    projection: Option<String>,
}

async fn data_availability(
    State(s): State<AppState>,
    Query(q): Query<DataAvailQuery>,
) -> Json<JsonValue> {
    let compact = q.compact.unwrap_or(false)
        || q.projection
            .as_deref()
            .map(|p| p.eq_ignore_ascii_case("compact"))
            .unwrap_or(false);
    Json(data_availability_json(&s, compact))
}

/// Core of `/v1/data_availability`. `compact` drops the per-band prose so a
/// full catalog fits the MCP wire budget; the MCP dispatch passes `true`
/// (the wire is the constrained path), REST defaults to `false`.
fn data_availability_json(s: &AppState, compact: bool) -> JsonValue {
    let pubkey_b32 = data_encoding::BASE32_NOPAD
        .encode(&s.identity.pubkey.0)
        .to_lowercase();
    let mut entries: Vec<JsonValue> = Vec::new();
    for band in all_materializable_bands() {
        let Some(meta) = band_materializer_meta(&band) else {
            continue;
        };
        let backfill_supported = !matches!(meta.kind, BandKind::NowOnly);
        if compact {
            entries.push(json!({
                "band": band,
                "kind": meta.kind.as_str(),
                "tempo": format!("{:?}", meta.tempo).to_lowercase(),
                "backfill_supported": backfill_supported,
            }));
        } else {
            let from_iso = meta
                .history_from_unix
                .and_then(|u| u64::try_from(u).ok())
                .map(iso8601_utc);
            let to_iso = meta
                .history_to_unix
                .and_then(|u| u64::try_from(u).ok())
                .map(iso8601_utc);
            entries.push(json!({
                "band": band,
                "kind": meta.kind.as_str(),
                "tempo": format!("{:?}", meta.tempo).to_lowercase(),
                "tempo_seconds": meta.tempo.slot_seconds(),
                "tslot_grid_seconds": meta.tempo.slot_seconds(),
                "history_available_from_unix": meta.history_from_unix,
                "history_available_to_unix": meta.history_to_unix,
                "history_available_from_iso": from_iso,
                "history_available_to_iso": to_iso,
                "upstream_wire_path": meta.wire_path,
                "backfill_supported": backfill_supported,
            }));
        }
    }
    let mut out = json!({
        "schema": "emem.data_availability.v1",
        "responder_pubkey_b32": pubkey_b32,
        "auto_materialize_enabled": auto_materialize_enabled(),
        "tessera_vintages": TESSERA_YEARS_RANGE_PUBLIC.clone().collect::<Vec<_>>(),
        "entries_count": entries.len(),
        "entries": entries,
    });
    if compact {
        if let Some(o) = out.as_object_mut() {
            o.insert("projection".into(), json!("compact"));
            o.insert(
                "projection_note".into(),
                json!("compact: {band, kind, tempo, backfill_supported} per band so the full band array survives the MCP wire budget. Call GET /v1/data_availability (REST, uncapped) or add ?projection=full for the per-band history window + upstream_wire_path."),
            );
        }
    } else if let Some(o) = out.as_object_mut() {
        o.insert(
            "kinds".into(),
            json!([
                {"name": "static",          "meaning": "single signed fact valid for all time (Cop-DEM, GMRT, JRC GSW recurrence)"},
                {"name": "annual_snapshot", "meaning": "one fact per calendar year on Jan 1 UTC (Tessera per-year)"},
                {"name": "annual_stack",    "meaning": "stack of multiple annual snapshots fused into one fact (Tessera multi-year 1024-D)"},
                {"name": "time_series",     "meaning": "per-tslot historical series fetched on demand from a STAC-style archive (Sentinel-2 L2A, Sentinel-1 RTC, MODIS NDVI)"},
                {"name": "now_only",        "meaning": "provider only exposes current value plus short forecast, no historical record (met.no)"},
                {"name": "per_release",     "meaning": "versioned global snapshot, each release replaces the previous (Overture Maps)"}
            ]),
        );
    }
    out
}

/// `GET /v1/fleet`, declare the satellite/sensor lineage that feeds each
/// materialized band. The protocol-level contract is the *band manifest*;
/// this endpoint is the editorial layer that names the actual hardware
/// platforms and their cadences, so an agent can decide "I need 15-min
/// observation rate" or "I need radar so it works at night" without
/// reading every band's documentation.
///
/// The mapping is keyed by upstream sensor (TerrA-MODIS, GMRT multibeam,
/// Cop-DEM 30m, etc.) → list of bands that derive from it. Geostationary
/// weather satellites (GOES-16/17/18, Himawari-9, Meteosat-9/11) are
/// declared as the *cadence source* for the weather bands even though
/// the wire path goes through Open-Meteo's NWP blend, this matches how
/// the temporal router classifies these bands as `ultra_fast`.
/// `GET /v1/coverage_matrix`, observability layer that lets agents (and
/// operators) see, in one call, which bands are *actually being answered*
/// by the responder right now. Combines the static manifest (what bands
/// exist), the materializer registry (what we know how to fetch), and the
/// live storage index (what we have).
///
/// For every band in the active manifest plus every materializer-only band
/// (modis.ndvi_mean, gmrt.topobathy_mean, copdem30m.elevation_mean,
/// indices.*, s2.*, sentinel1_raw, geotessera.*, weather.*) we surface:
///   - has_materializer: bool, wired into try_materialize_bands?
///   - facts_count       : u64, distinct (cell, tslot) pairs cached
///   - last_attested_at  : ISO 8601, when the responder last signed under
///     this band; helps an agent cite the freshest band for a query
///   - tempo / family    : from the manifest, for the temporal router
///   - sat_lineage       : satellite/sensor names from the fleet declaration
///
/// O(N) over the full storage index; capped by EMEM_COVERAGE_MATRIX_LIMIT
/// (default 50_000) so big deployments don't blow the response.
async fn coverage_matrix(State(s): State<AppState>) -> Json<JsonValue> {
    use std::collections::BTreeMap;
    // Clamp the operator-provided limit to a sane range. An unbounded
    // value lets a single anonymous GET pin the storage index scan for
    // arbitrarily long; below 1k the matrix loses utility. 100k is
    // already ~enough memory pressure that we don't want callers
    // raising it accidentally.
    let limit: usize = std::env::var("EMEM_COVERAGE_MATRIX_LIMIT")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(50_000)
        .clamp(1_000, 100_000);

    // Aggregate over the storage index. For each entry we resolve the
    // actual fact and parse its `signed_at` to get a real wall-clock
    // last-attested per band. This is one cache get_many call per ~256
    // entries (chunked) so a 50k-entry deployment still answers in
    // sub-second range. Entries with non-zero tslots that *look* like
    // unix timestamps still update the bound (cheap path) so weather/
    // index bands surface freshness even when the get_many lookup is
    // slow or partial.
    let mut counts: BTreeMap<String, (u64, Option<i64>)> = BTreeMap::new();
    if let Ok(entries) = s.storage.iter_index(Some(limit)).await {
        // First pass: counts + tslot proxy (cheap, no fact lookups).
        let mut cids: Vec<emem_fact::FactCid> = Vec::with_capacity(entries.len());
        let mut keys: Vec<emem_cache::CanonicalKey> = Vec::with_capacity(entries.len());
        for (k, cid) in entries {
            let entry = counts.entry(k.band.clone()).or_insert((0, None));
            entry.0 += 1;
            if k.tslot >= 1_577_836_800 {
                let cur = entry.1.unwrap_or(0);
                if (k.tslot as i64) > cur {
                    entry.1 = Some(k.tslot as i64);
                }
            }
            cids.push(cid);
            keys.push(k);
        }
        // Second pass: chunked fact resolution to pick up signed_at on
        // bands whose tslot is 0 (static bands like copdem, koppen, dem)
        // or non-timestamp-shaped (foundation embedding tslots).
        const CHUNK: usize = 256;
        for (chunk_keys, chunk_cids) in keys.chunks(CHUNK).zip(cids.chunks(CHUNK)) {
            if let Ok(facts) = s.storage.get_facts_many(chunk_cids).await {
                for (k, fact) in chunk_keys.iter().zip(facts) {
                    let signed_at_unix = match fact.as_ref() {
                        Some(emem_fact::Fact::Primary(p)) => parse_iso8601_unix(&p.signed_at),
                        Some(emem_fact::Fact::Absence(n)) => parse_iso8601_unix(&n.signed_at),
                        _ => None,
                    };
                    if let Some(ts) = signed_at_unix {
                        let entry = counts.entry(k.band.clone()).or_insert((0, None));
                        let cur = entry.1.unwrap_or(0);
                        if ts > cur {
                            entry.1 = Some(ts);
                        }
                    }
                }
            }
        }
    }

    // Bands that ship a materializer in this build, with metadata for the agent.
    let materializer_bands: &[(&str, &str, &str, &[&str])] = &[
        ("modis.ndvi_mean", "medium", "vegetation",
            &["Terra (NASA EOS AM-1) MODIS"]),
        ("gmrt.topobathy_mean", "static", "terrain",
            &["GMRT (Lamont-Doherty multibeam fleet)"]),
        ("copdem30m.elevation_mean", "static", "terrain",
            &["TanDEM-X / Copernicus DEM"]),
        ("geotessera", "slow", "foundation",
            &["Tessera v1 (Cambridge AAILab + Clay-style composite)"]),
        ("geotessera.multi_year", "slow", "foundation",
            &["Tessera v1 multi-year (2017-2024 stacked, 1024-D)"]),
        ("geotessera.2017", "slow", "foundation", &["Tessera v1 2017"]),
        ("geotessera.2018", "slow", "foundation", &["Tessera v1 2018"]),
        ("geotessera.2019", "slow", "foundation", &["Tessera v1 2019"]),
        ("geotessera.2020", "slow", "foundation", &["Tessera v1 2020"]),
        ("geotessera.2021", "slow", "foundation", &["Tessera v1 2021"]),
        ("geotessera.2022", "slow", "foundation", &["Tessera v1 2022"]),
        ("geotessera.2023", "slow", "foundation", &["Tessera v1 2023"]),
        ("geotessera.2024", "slow", "foundation", &["Tessera v1 2024"]),
        ("geotessera.bin128", "slow", "foundation",
            &["Derived: turboquant rotation + sign-bit pack of geotessera vector (int8+scale upstream, decoded f32 via recall). 16 B/cell on disk; Hamming-distance triage k-NN at ~10⁹ pairs/sec/core. Designed to feed `find_similar` mode=hamming / hamming_then_rerank, the full vector under `geotessera` is still attested for re-rank."]),
        ("indices.ndvi", "fast", "vegetation", &["Sentinel-2A/B/C MSI (NDVI)"]),
        ("indices.ndwi", "fast", "water",      &["Sentinel-2A/B/C MSI (NDWI Gao)"]),
        ("indices.mndwi", "fast", "water",     &["Sentinel-2A/B/C MSI (MNDWI McFeeters)"]),
        ("indices.evi", "fast", "vegetation",  &["Sentinel-2A/B/C MSI (EVI)"]),
        ("indices.nbr", "fast", "fire",        &["Sentinel-2A/B/C MSI (NBR)"]),
        ("indices.ndmi", "fast", "vegetation", &["Sentinel-2A/B/C MSI (NDMI)"]),
        ("indices.savi", "fast", "vegetation", &["Sentinel-2A/B/C MSI (SAVI)"]),
        ("indices.bsi",  "fast", "soil",       &["Sentinel-2A/B/C MSI (BSI)"]),
        ("indices.ndbi", "fast", "human",      &["Sentinel-2A/B/C MSI (NDBI built-up)"]),
        ("s2.B01", "fast", "optical", &["Sentinel-2A/B/C MSI B01 60m coastal aerosol"]),
        ("s2.B02", "fast", "optical", &["Sentinel-2A/B/C MSI B02 10m blue"]),
        ("s2.B03", "fast", "optical", &["Sentinel-2A/B/C MSI B03 10m green"]),
        ("s2.B04", "fast", "optical", &["Sentinel-2A/B/C MSI B04 10m red"]),
        ("s2.B05", "fast", "optical", &["Sentinel-2A/B/C MSI B05 20m red-edge 1"]),
        ("s2.B06", "fast", "optical", &["Sentinel-2A/B/C MSI B06 20m red-edge 2"]),
        ("s2.B07", "fast", "optical", &["Sentinel-2A/B/C MSI B07 20m red-edge 3"]),
        ("s2.B08", "fast", "optical", &["Sentinel-2A/B/C MSI B08 10m wide NIR"]),
        ("s2.B8A", "fast", "optical", &["Sentinel-2A/B/C MSI B8A 20m narrow NIR"]),
        ("s2.B09", "fast", "optical", &["Sentinel-2A/B/C MSI B09 60m water vapor"]),
        ("s2.B11", "fast", "optical", &["Sentinel-2A/B/C MSI B11 20m SWIR-1"]),
        ("s2.B12", "fast", "optical", &["Sentinel-2A/B/C MSI B12 20m SWIR-2"]),
        ("s2.scl", "fast", "vision",  &["Sentinel-2 L2A scene-classification (uint8 0..11)"]),
        ("sentinel1_raw", "fast", "radar",
            &["Sentinel-1A/C C-band SAR (RTC γ0 VV in dB) via Microsoft Planetary Computer"]),
        ("surface_water.recurrence", "static", "water",
            &["JRC Global Surface Water v1.4 (Pekel et al. 2016, Landsat-derived 1984-2021 inter-annual recurrence climatology)"]),
        ("koppen", "static", "climate",
            &["Beck Köppen-Geiger v1 1-km present-day classification (Beck et al. 2018, Sci Data 5:180214; CC-BY-4.0)"]),
        ("weather.temperature_2m", "ultra_fast", "climate",
            &["MET Norway api.met.no, sat-fed via ECMWF + EUMETSAT geostationary fleet"]),
        ("weather.cloud_cover", "ultra_fast", "climate",
            &["MET Norway api.met.no"]),
        ("weather.precipitation_mm", "ultra_fast", "climate",
            &["MET Norway api.met.no"]),
        ("weather.wind_speed_10m", "ultra_fast", "climate",
            &["MET Norway api.met.no"]),
        ("weather.relative_humidity_2m", "ultra_fast", "climate",
            &["MET Norway api.met.no, instant.details.relative_humidity"]),
        ("weather.dew_point_2m", "ultra_fast", "climate",
            &["MET Norway api.met.no, instant.details.dew_point_temperature"]),
        ("weather.air_pressure_msl", "ultra_fast", "climate",
            &["MET Norway api.met.no, instant.details.air_pressure_at_sea_level"]),
        ("weather.wind_direction_10m", "ultra_fast", "climate",
            &["MET Norway api.met.no, instant.details.wind_from_direction"]),
        ("overture.buildings.count", "slow", "human",
            &["Overture Maps Foundation buildings parquet (anonymous S3)"]),
        ("overture.places.count", "slow", "human",
            &["Overture Maps Foundation places parquet (anonymous S3)"]),
        ("overture.transportation.road_length_m", "slow", "human",
            &["Overture Maps Foundation transportation parquet (anonymous S3)"]),
        // WDPA-equivalent protected-area lookup. Source-of-record is
        // OpenStreetMap `boundary=protected_area` polygons via the public
        // Overpass API (point-in-polygon `is_in()` filter); OSM mirrors
        // the same designations WDPA tracks (NPS / USFWS / IUCN / EU
        // CDDA) and tags `protect_class` 1..6 → IUCN Ia..VI. Protected
        // Planet's own REST API requires an account-gated token, so OSM
        // is the canonical open-data path.
        ("protected", "static", "human",
            &["OpenStreetMap WDPA mirror (Overpass API, boundary=protected_area + protect_class → IUCN)"]),
    ];
    let mat_set: std::collections::HashSet<&str> = materializer_bands.iter().map(|t| t.0).collect();

    let registry = &*emem_core::bands::DEFAULT;
    let mut bands_json: Vec<JsonValue> = Vec::new();
    let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();

    // Cube placeholder slots are family aliases (`dem`, `cop_dem`,
    // `climate`, `indices`, `landcover`, …), they reserve cube offsets
    // for a *family* of attestable sub-keys and are not themselves
    // directly materialized. Without this map, the coverage matrix
    // shows `cop_dem mat=False facts=0` next to a working
    // `copdem30m.elevation_mean mat=True`, which makes agents conclude
    // "DEM is offline" when in fact it's wired under a different key.
    //
    // Source of truth: `Band.scalar_keys` from `bands-v0.json`,
    // intersected with `band_materializer_meta(child).is_some()` (the
    // canonical wired-band predicate). No hardcoded sub-key tables -
    // adding a child to the registry automatically surfaces it here.
    // The same registry CID input always produces the same alias map,
    // so this is deterministic and federation-safe.
    let cube_aliases: BTreeMap<String, Vec<String>> = registry
        .bands
        .iter()
        .map(|b| {
            let wired: Vec<String> = b
                .scalar_keys
                .iter()
                .filter(|child| {
                    // A child is "wired" iff this responder has a
                    // materializer for it. Family-bands whose own key
                    // is materializable (e.g. `geotessera`,
                    // `sentinel1_raw`) include themselves so the alias
                    // map remains a complete list of attestable keys.
                    band_materializer_meta(child).is_some() || mat_set.contains(child.as_str())
                })
                .cloned()
                .collect();
            (b.key.clone(), wired)
        })
        .collect();
    let alias_for =
        |k: &str| -> &[String] { cube_aliases.get(k).map(|v| v.as_slice()).unwrap_or(&[]) };
    let aggregate_subkey_facts = |subkeys: &[String]| -> (u64, Option<i64>) {
        let mut n_total = 0u64;
        let mut latest: Option<i64> = None;
        for k in subkeys {
            if let Some((n, last)) = counts.get(k) {
                n_total += *n;
                if let Some(t) = last {
                    latest = Some(latest.map_or(*t, |x| x.max(*t)));
                }
            }
        }
        (n_total, latest)
    };

    let pubkey_b32 = data_encoding::BASE32_NOPAD
        .encode(&s.identity.pubkey.0)
        .to_lowercase();

    // Cube bands first, every entry from bands-v0.json. For family
    // alias slots we surface the wired sub-keys so an agent reading
    // this view is never told a family is offline when its sub-keys
    // are live.
    for b in &registry.bands {
        seen.insert(b.key.clone());
        let (n_self, last_self) = counts.get(&b.key).copied().unwrap_or((0, None));
        let direct_mat = mat_set.contains(b.key.as_str());
        let subkeys = alias_for(b.key.as_str());
        // A band is a family alias when its registry-declared
        // `scalar_keys` includes at least one *distinct* wired child -
        // `sentinel1_raw` listing only itself is NOT a family alias,
        // but `cop_dem` listing `copdem30m.elevation_mean` IS.
        let is_family_alias = subkeys.iter().any(|k| k != &b.key);
        let (n_sub, last_sub) = if is_family_alias {
            aggregate_subkey_facts(subkeys)
        } else {
            (0, None)
        };
        let n = n_self + n_sub;
        let last = match (last_self, last_sub) {
            (Some(a), Some(b)) => Some(a.max(b)),
            (Some(a), None) | (None, Some(a)) => Some(a),
            (None, None) => None,
        };
        let has_mat = direct_mat
            || is_family_alias
                && subkeys
                    .iter()
                    .any(|k| mat_set.contains(k.as_str()) || band_materializer_meta(k).is_some());
        let sat_lineage: Vec<&str> = materializer_bands
            .iter()
            .find(|t| t.0 == b.key.as_str())
            .map(|t| t.3.to_vec())
            .unwrap_or_default();
        let meta = band_materializer_meta(b.key.as_str());
        let history_from = meta.as_ref().and_then(|m| m.history_from_unix);
        let history_to = meta.as_ref().and_then(|m| m.history_to_unix);
        // Build the per-subkey detail array. Always emit the field
        // (even as `[]`) so agents can discriminate "no children"
        // from "field missing / handler hasn't been updated".
        let wired_subkeys_detail: Vec<JsonValue> = subkeys
            .iter()
            .map(|k| {
                let m = band_materializer_meta(k);
                let kind = m.as_ref().map(|m| m.kind.as_str()).unwrap_or("unknown");
                let has_mat = m.is_some() || mat_set.contains(k.as_str());
                json!({
                    "key": k,
                    "kind": kind,
                    "has_materializer": has_mat,
                    "source_scheme": source_scheme_for(k),
                })
            })
            .collect();
        let mut row = json!({
            "band":             b.key,
            "family":           format!("{:?}", b.family).to_ascii_lowercase(),
            "tempo":            format!("{:?}", b.tempo).to_ascii_lowercase(),
            "tempo_seconds":    b.tempo.slot_seconds(),
            "in_cube":          true,
            "cube_offset":      b.offset,
            "cube_dims":        b.dims,
            "has_materializer": has_mat,
            "facts_count":      n,
            "last_attested_unix_s": last,
            "sat_lineage":      sat_lineage,
            "history_available_from_unix": history_from,
            "history_available_to_unix":   history_to,
            "responder_pubkey_b32": pubkey_b32,
            // Honest default: empty array, never null and never
            // omitted. Agents that see this field can rely on it being
            // present on every band row.
            "wired_subkeys":    wired_subkeys_detail,
        });
        if is_family_alias {
            row.as_object_mut()
                .unwrap()
                .insert("is_family_alias".into(), JsonValue::Bool(true));
        }
        bands_json.push(row);
    }
    // Auxiliary materializer-only bands (not in the cube). These are
    // leaf scalar bands, never family aliases, `wired_subkeys` is
    // always `[]` here, but we emit the field so agents can
    // unconditionally read `row["wired_subkeys"]` without a presence
    // check (honest defaults rule, see commit notes).
    for (key, tempo, family, sats) in materializer_bands {
        if seen.contains(*key) {
            continue;
        }
        let (n, last) = counts.get(*key).copied().unwrap_or((0, None));
        let meta = band_materializer_meta(key);
        let tempo_seconds = meta.as_ref().map(|m| m.tempo.slot_seconds()).unwrap_or(0);
        let history_from = meta.as_ref().and_then(|m| m.history_from_unix);
        let history_to = meta.as_ref().and_then(|m| m.history_to_unix);
        bands_json.push(json!({
            "band":             key,
            "family":           family,
            "tempo":            tempo,
            "tempo_seconds":    tempo_seconds,
            "in_cube":          false,
            "has_materializer": true,
            "facts_count":      n,
            "last_attested_unix_s": last,
            "sat_lineage":      sats,
            "history_available_from_unix": history_from,
            "history_available_to_unix":   history_to,
            "responder_pubkey_b32": pubkey_b32,
            "wired_subkeys":    JsonValue::Array(Vec::new()),
        }));
    }

    // Roll-ups for the agent's at-a-glance view.
    let total_bands = bands_json.len();
    let total_facts: u64 = counts.values().map(|(n, _)| *n).sum();
    let with_materializer = bands_json
        .iter()
        .filter(|b| {
            b.get("has_materializer")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
        })
        .count();
    let with_facts = bands_json
        .iter()
        .filter(|b| b.get("facts_count").and_then(|v| v.as_u64()).unwrap_or(0) > 0)
        .count();

    // Top-level family-alias summary so an agent can read the whole
    // alias map in one shot without iterating `bands[]`. Derived from
    // the same `cube_aliases` map built above, only family bands
    // (those with at least one *distinct* wired child) are included,
    // and entries are key-only (the per-child detail lives in the
    // band row's `wired_subkeys[]`). The map is sorted by family key
    // (BTreeMap iteration order) so the response is deterministic.
    let family_aliases_summary: serde_json::Map<String, JsonValue> = cube_aliases
        .iter()
        .filter(|(family, subs)| subs.iter().any(|k| k != *family))
        .map(|(family, subs)| {
            (
                family.clone(),
                JsonValue::Array(subs.iter().map(|k| JsonValue::String(k.clone())).collect()),
            )
        })
        .collect();

    Json(json!({
        "schema": "emem.coverage_matrix.v1",
        "totals": {
            "bands_declared": total_bands,
            "bands_with_materializer": with_materializer,
            "bands_with_facts": with_facts,
            "total_facts": total_facts,
            "iter_index_limit": limit,
        },
        "responder_pubkey_b32": data_encoding::BASE32_NOPAD
            .encode(&s.identity.pubkey.0).to_lowercase(),
        "bands": bands_json,
        "family_aliases": family_aliases_summary,
        "agent_hint": {
            "use_when": "Decide which band to /v1/recall before paying for materialization. has_materializer=false bands need a third-party signed Attestation; in_cube=false bands ride alongside the 1792-D layout but aren't byte-addressable in the cube.",
            "family_aliases": "Some cube slots reserve byte ranges for a *family* of attestable sub-keys; recall calls go to the granular subkey, not the family slot. When `is_family_alias=true`, the row reports rolled-up `facts_count` and a per-band `wired_subkeys[]` array of `{key, kind, has_materializer, source_scheme}` so the agent can pick the actual band to materialize. The top-level `family_aliases` object summarises the same map family→[subkey,…] for one-shot scanning. Both are derived from `bands-v0.json` `scalar_keys` intersected with the materializer registry, no hardcoded sub-key tables, deterministic per registry CID.",
            "freshness": "facts_count>0 with a recent last_attested_unix_s means the band has been answered globally somewhere recently; per-cell freshness still needs /v1/temporal_route.",
            "history_bounds": "history_available_from_unix / history_available_to_unix bound what an `emem_backfill` call can materialize on this responder. `null` = the band has no historical materializer here (e.g. weather nowcast, Overture snapshot, or static climatology where one fact answers for all time).",
            "tempo_seconds": "Slot duration in seconds. 0 = static (one fact). Use it to convert between Unix epoch and tslot when planning a backfill window.",
            "federation": "responder_pubkey_b32 is the ed25519 key that signs every fact for this band at this responder. When the directory grows beyond one responder, the same band may be signed by different pubkeys across responders, agents should treat (responder_pubkey, fact_cid) as the unit of trust.",
            "fleet": "/v1/fleet for per-platform sensor lineage (cadence, swath, native_res_m).",
        },
    }))
}

