    /// Boring API contract: every band that emem materializes natively
    /// from a 10 m sensor (Sentinel-1 / Sentinel-2 reflectance and
    /// derived indices) must report `data_resolution_m == 10`. This is
    /// the multimodal-fusion guarantee, if it ever regresses, the
    /// "10 m fidelity" claim in CLIENTS.md and ai-plugin.json starts
    /// lying about the data.
    #[test]
    fn band_input_resolution_m_matches_sensor_pitch() {
        // Sentinel-2 reflectance + indices: 10 m
        for band in [
            "s2.B04",
            "s2.B08",
            "s2.B11",
            "indices.ndvi",
            "indices.bsi",
            "indices.ndmi",
            "indices.urban_canopy_index",
        ] {
            assert_eq!(
                band_input_resolution_m(band),
                Some(10),
                "{band}: expected 10 m S2 pitch"
            );
        }
        // Sentinel-1 RTC: 10 m
        assert_eq!(band_input_resolution_m("sentinel1_raw"), Some(10));
        // Cop-DEM GLO-30 30 m, SoilGrids 250 m, MODIS LST 1 km, CAMS 11 km.
        // The responder fetches the GLO-30 product (AWS Open Data
        // `copernicus-dem-30m` COG mirror, migrated 2026-05-29), so the
        // input pitch is 30 m, not the 90 m of the retired Open-Meteo
        // per-point path.
        assert_eq!(
            band_input_resolution_m("copdem30m.elevation_mean"),
            Some(30)
        );
        assert_eq!(band_input_resolution_m("soilgrids.soc_0_30cm"), Some(250));
        assert_eq!(band_input_resolution_m("modis.lst_day_8day"), Some(1000));
        assert_eq!(band_input_resolution_m("cams.pm25"), Some(11_000));
    }

    /// The cell-grid constant must stay 10 m at the equator. This is
    /// the cell64 grain reported by `/v1/grid_info` and surfaced as
    /// `cell_dedupe_m` on every boring response. The codec itself
    /// (emem-codec/src/geo.rs) is the source of truth for the bit
    /// budget; this test guards lock-step with that crate.
    #[test]
    fn cell_dedupe_constant_matches_active_grid() {
        assert_eq!(RESOLUTION_M_GRID, 10);
    }

    /// Two queries 12 m apart on the same cell64 MUST resolve to
    /// distinct cells, the global 10 m grid is the corruption guard
    /// the older fine_cell suffix used to provide. (The codec test
    /// `cells_distinguish_12_metre_neighbors` proves this at the
    /// codec layer; here we just sanity-check the boring API plumbing
    /// goes through `cell_from_latlng` and not a coarser path.)
    #[test]
    fn boring_recall_cells_distinguish_at_10_metres() {
        let a = emem_codec::cell_from_latlng(30.5, 75.85);
        let b = emem_codec::cell_from_latlng(30.5, 75.85 + 1.08e-4);
        assert_ne!(
            emem_codec::to_cell64(a),
            emem_codec::to_cell64(b),
            "12 m east must produce a distinct cell64, corruption guard"
        );
    }

    /// Regression for P0-2 of the 2026-05-05 deepscan: family-alias
    /// bands like `air_quality` (whose own key has no materializer)
    /// must surface their wired children under `wired_subkeys[]` in
    /// `/v1/coverage_matrix`. Before this fix, agents reading
    /// `air_quality has_materializer=false facts_count=0` would
    /// conclude "no air-quality data" even though `cams.pm25 / cams.no2
    /// / cams.so2 / cams.aod_550 / …` were fully wired.
    ///
    /// This test exercises the same registry-derived projection the
    /// coverage_matrix handler uses (no AppState / network needed) so
    /// the contract is locked at the data-layer: any future edit to
    /// `bands-v0.json` that drops the `cams.*` scalar_keys, or any
    /// edit to `band_materializer_meta` that drops the `cams.*` arm,
    /// will fail this test before reaching agents.
    #[test]
    fn coverage_matrix_air_quality_surfaces_wired_cams_subkeys() {
        let registry = &*emem_core::bands::DEFAULT;
        let aq = registry
            .lookup("air_quality")
            .expect("air_quality band missing from registry, P0-2 contract");
        // The registry must declare cams.* scalar_keys.
        let declared: Vec<&str> = aq.scalar_keys.iter().map(|s| s.as_str()).collect();
        assert!(
            declared.iter().any(|k| k.starts_with("cams.")),
            "air_quality.scalar_keys lost its cams.* children: {declared:?}"
        );
        // Apply the same derivation `coverage_matrix` does: keep only
        // the children for which a materializer is wired.
        let wired: Vec<&str> = declared
            .iter()
            .copied()
            .filter(|child| band_materializer_meta(child).is_some())
            .collect();
        assert!(
            !wired.is_empty(),
            "air_quality has scalar_keys {declared:?} but none route to a wired materializer, \
             coverage_matrix would tell agents the family is offline"
        );
        // Concretely: the four canonical AQI pollutants must all be
        // wired so a question like "what's the air quality here?"
        // doesn't silently degrade.
        for must_have in ["cams.pm25", "cams.no2", "cams.so2", "cams.aod_550"] {
            assert!(
                wired.contains(&must_have),
                "expected {must_have} in air_quality wired_subkeys, got {wired:?}"
            );
        }
        // The family band itself must NOT have a direct materializer
        //, this is precisely the shape that triggered the P0 (a band
        // entry whose `has_materializer=false` hides wired children).
        assert!(
            band_materializer_meta("air_quality").is_none(),
            "air_quality grew its own materializer, update this test, it no longer reproduces \
             the family-alias hiding bug"
        );
        // And the source-scheme helper must group all wired children
        // under the same scheme (`cams`) so an agent can filter by
        // upstream provider.
        for k in &wired {
            assert_eq!(
                source_scheme_for(k),
                "cams",
                "{k} routes through a non-cams scheme: {:?}",
                source_scheme_for(k)
            );
        }
    }

    /// P1-B regression: the `forest_change` family band MUST declare
    /// `forest_change.lossyear` (and siblings) under `scalar_keys`
    /// AND each child MUST resolve to a wired materializer. This is
    /// the same family-alias pattern as `air_quality`/`cams.*` -
    /// without it, agents asking the deepscan eval question "Has
    /// this been deforested since 2010?" hit the cube placeholder
    /// `forest_change` and conclude "no Hansen GFC", even though the
    /// `forest_change.lossyear` materializer is fully wired against
    /// the public `earthenginepartners-hansen` GCS bucket.
    #[test]
    fn coverage_matrix_forest_change_surfaces_wired_subkeys() {
        let registry = &*emem_core::bands::DEFAULT;
        let fc = registry
            .lookup("forest_change")
            .expect("forest_change band missing from registry");
        let declared: Vec<&str> = fc.scalar_keys.iter().map(|s| s.as_str()).collect();
        // Sub-bands under `forest_change` must include the three
        // canonical Hansen GFC layers, anything less and the eval
        // question "deforested since YYYY?" can't resolve.
        for must_have in [
            "forest_change.lossyear",
            "forest_change.treecover2000",
            "forest_change.gain",
        ] {
            assert!(
                declared.contains(&must_have),
                "forest_change.scalar_keys missing {must_have}: {declared:?}"
            );
        }
        // Every declared child MUST route to a wired materializer.
        for child in &declared {
            assert!(
                band_materializer_meta(child).is_some(),
                "forest_change child {child} has no band_materializer_meta arm, \
                 agents will see the family as offline"
            );
        }
        // The family band itself must NOT have a direct materializer
        // (forest_change is the cube placeholder; recall goes to the
        // sub-band keys via the family-alias projection).
        assert!(
            band_materializer_meta("forest_change").is_none(),
            "forest_change grew its own materializer, update this test"
        );
    }

    /// Companion guard for the same P0: walk every cube band and
    /// assert that whenever the family band itself is *not*
    /// directly materialized AND it declares any scalar_keys, the
    /// derived `wired_subkeys[]` must be honest, either a
    /// non-empty list of wired children, OR an empty list (legacy
    /// `dem` / `landcover` slots whose registry scalar_keys are
    /// editorial-only and not yet wired). The point is: NEVER
    /// silently drop the field, NEVER hide a wired child, NEVER
    /// invent one. This locks the registry → handler projection
    /// against drift.
    #[test]
    fn coverage_matrix_family_aliases_derive_deterministically() {
        let registry = &*emem_core::bands::DEFAULT;
        let mut aliases_with_wired_children: Vec<(&str, Vec<&str>)> = Vec::new();
        for b in &registry.bands {
            if b.scalar_keys.is_empty() {
                continue;
            }
            let wired: Vec<&str> = b
                .scalar_keys
                .iter()
                .filter(|child| band_materializer_meta(child).is_some())
                .map(|s| s.as_str())
                .collect();
            // If the family has at least one *distinct* wired child,
            // it counts as a true alias (sentinel1_raw lists only
            // itself, so it doesn't).
            if wired.iter().any(|k| *k != b.key.as_str()) {
                aliases_with_wired_children.push((b.key.as_str(), wired));
            }
        }
        // Sanity floor: at minimum we expect air_quality, cop_dem,
        // overture, and climate to come through with wired children.
        // (Dropping any of these without an agent-facing migration
        // would re-introduce the P0.)
        for required in ["air_quality", "cop_dem", "overture", "climate"] {
            assert!(
                aliases_with_wired_children
                    .iter()
                    .any(|(k, v)| *k == required && !v.is_empty()),
                "family alias {required} lost its wired children, agents will conclude the \
                 family is offline. Got map: {aliases_with_wired_children:?}"
            );
        }
    }

