    #[test]
    fn equal_area_weight_drops_to_zero_at_poles() {
        // At the equator the weight must be ~1.0, a unit-area cell
        // contributes its full sample. At lat 89.99 the weight must be
        // tiny (cos(89.99°) ≈ 1.7e-4), a polar cell barely contributes
        // to an equal-area mean. These are the contract the cos(lat)
        // reweighting in `aggregate_band` relies on.
        let equator = emem_codec::cell64_from_latlng(0.0, 0.0);
        let pole = emem_codec::cell64_from_latlng(89.99, 0.0);
        let w_eq = emem_codec::equal_area_weight_for(&equator);
        let w_pole = emem_codec::equal_area_weight_for(&pole);
        assert!(
            (w_eq - 1.0).abs() < 1e-3,
            "equator weight should be ≈ 1.0, got {w_eq}"
        );
        assert!(
            w_pole < 1e-2,
            "pole weight should drop to near 0, got {w_pole}"
        );
        // Unparseable cells fall back to 1.0, no panic, no NaN.
        assert!(
            (emem_codec::equal_area_weight_for("not-a-cell64") - 1.0).abs() < 1e-12,
            "decode failure must degrade silently to weight 1.0"
        );
    }

    #[test]
    fn aggregate_mean_drifts_toward_low_latitude_when_values_grow_with_latitude() {
        // 100 cells from lat -60..+60 with value = lat. Symmetric in
        // both reductions (unweighted mean = 0; cos(lat)-weighted mean
        // also = 0 because weight is even in lat). Sanity that the
        // reweighting doesn't break symmetric distributions.
        let n: usize = 100;
        let lats: Vec<f64> = (0..n)
            .map(|i| -60.0 + 120.0 * (i as f64) / ((n - 1) as f64))
            .collect();
        let cells: Vec<String> = lats
            .iter()
            .enumerate()
            .map(|(i, lat)| {
                // Spread longitudes apart so cell64 quantisation doesn't
                // collide neighbours into the same bucket.
                emem_codec::cell64_from_latlng(*lat, -179.0 + 3.0 * i as f64)
            })
            .collect();
        let signed_values: Vec<JsonValue> = lats.iter().map(|lat| json!(*lat)).collect();
        let (_, headline, stats, _, _) =
            aggregate_band(AggKind::NumericScalar, &cells, &signed_values, n, 0);
        let mean = headline.as_f64().unwrap();
        let unweighted_signed: f64 = lats.iter().sum::<f64>() / n as f64;
        assert!(
            mean.abs() < 0.5,
            "symmetric signed-lat distribution should average to ~0, got {mean}"
        );
        assert!(
            unweighted_signed.abs() < 0.5,
            "unweighted reference mean also ~0, got {unweighted_signed}"
        );
        // `stats.cos_lat_weighting_applied` must be true so an agent
        // can see the projection without re-reading docs.
        assert_eq!(
            stats
                .get("cos_lat_weighting_applied")
                .and_then(|v| v.as_bool()),
            Some(true)
        );

        // Now values = abs(lat). Unweighted mean ≈ 30 (mean of [0..60]
        // mirrored); equal-area-weighted mean drifts down because the
        // polar samples (where |lat| is large) get down-weighted by
        // cos(lat). Analytical reference for the continuous case:
        //   ∫₀^{π/3} (180/π)·u·cos(u) du / ∫₀^{π/3} cos(u) du
        // resolves to ≈ 26.91°, which the discrete 100-cell sum
        // approximates closely.
        let abs_values: Vec<JsonValue> = lats.iter().map(|lat| json!(lat.abs())).collect();
        let (_, headline_abs, _, _, _) =
            aggregate_band(AggKind::NumericScalar, &cells, &abs_values, n, 0);
        let mean_abs = headline_abs.as_f64().unwrap();
        let unweighted_abs: f64 = lats.iter().map(|x| x.abs()).sum::<f64>() / n as f64;
        assert!(
            (unweighted_abs - 30.0).abs() < 1.0,
            "unweighted reference mean of |lat| over -60..60 ≈ 30, got {unweighted_abs}"
        );
        assert!(
            mean_abs < unweighted_abs,
            "equal-area weighted mean must drift toward low |lat| ({mean_abs} >= {unweighted_abs})"
        );
        assert!(
            (mean_abs - 26.91).abs() < 1.0,
            "weighted mean of |lat| over -60..60 ≈ 26.9° analytically, got {mean_abs}"
        );
    }

    #[test]
    fn mmu_floor_demotes_sub_05ha_failures() {
        // Dense sampling: 10 fail / 100 total over a 1 ha plot → 0.10 ha
        // failing-area projection. Below 0.5 ha → demote to below_mmu.
        let v = mmu_demote(10, 100, 1.0);
        assert_eq!(v.verdict_code, 6); // below_mmu
        assert!(v.failing_area_ha < 0.5);
        assert!(v.mmu_floor_applied);

        // 10 fail / 100 total over a 10 ha plot → 1.0 ha failing-area
        // projection. Above MMU → keep fail.
        let v2 = mmu_demote(10, 100, 10.0);
        assert_eq!(v2.verdict_code, 2);
        assert!(!v2.mmu_floor_applied);

        // Audit regression: the 12 kha plot bug. 22 fail / 512 total
        // over a 12,298 ha plot → ~528 ha failing-area projection
        // (NOT 0.20 ha from the old `n_fail × cell_area` math).
        // Must trigger fail, not below_mmu.
        let v3 = mmu_demote(22, 512, 12_298.67);
        assert_eq!(
            v3.verdict_code, 2,
            "polygon-projected fail must not be demoted to below_mmu"
        );
        assert!(
            v3.failing_area_ha > 0.5,
            "failing_area must project to polygon scale"
        );
        assert!(
            v3.failing_area_ha > 500.0,
            "12 kha plot at 4.3% should report >500 ha failing"
        );
    }

    #[test]
    fn verdict_label_has_no_de_minimis_variant() {
        // Strict EUDR has no de-minimis fail-fraction tolerance; the only
        // area floor is the Article 2(4) 0.5 ha MMU (code 6 = below_mmu).
        // Code 5 was a dead `fail_below_de_minimis` variant never emitted
        // by any code path, it must not resolve to a label.
        assert_eq!(verdict_label(1), "pass");
        assert_eq!(verdict_label(2), "fail");
        assert_eq!(verdict_label(3), "not_in_scope");
        assert_eq!(verdict_label(4), "indeterminate");
        assert_eq!(verdict_label(6), "below_mmu");
        assert_eq!(verdict_label(5), "unknown");

        // Every verdict code the aggregation/MMU logic can actually emit
        // resolves to a real, non-"unknown" label.
        for code in [1u8, 2, 3, 4, 6] {
            assert_ne!(
                verdict_label(code),
                "unknown",
                "emittable verdict code {code} must have a label"
            );
        }
    }

    #[test]
    fn forest_baseline_honest_when_jrc_missing() {
        // Every cell has Hansen tc = 100 but JRC = None, must surface
        // hansen_only_jrc_unavailable, NOT "jrc_gfc2020_v3".
        let cells = vec![
            EudrCellVerdict {
                cell: "c0".into(),
                verdict: 1,
                label: "pass",
                jrc_forest_2020: None,
                hansen_treecover_2000: Some(100),
                hansen_lossyear: Some(0),
                jrc_tmf_deforestation_year: None,
                wri_driver_class: None,
                radd_alert_date: None,
                refinement_applied: Some("jrc_unavailable_hansen_only"),
                borderline_canopy: false,
                fact_cids: vec![],
                lossyear_fact_cid: None,
            },
            EudrCellVerdict {
                cell: "c1".into(),
                verdict: 1,
                label: "pass",
                jrc_forest_2020: None,
                hansen_treecover_2000: Some(95),
                hansen_lossyear: Some(0),
                jrc_tmf_deforestation_year: None,
                wri_driver_class: None,
                radd_alert_date: None,
                refinement_applied: Some("jrc_unavailable_hansen_only"),
                borderline_canopy: false,
                fact_cids: vec![],
                lossyear_fact_cid: None,
            },
        ];
        assert_eq!(
            aggregate_baseline_provenance(&cells),
            "hansen_only_jrc_unavailable"
        );

        // JRC present at one cell → jrc_gfc2020_v3.
        let mut cells2 = cells.clone();
        cells2[0].jrc_forest_2020 = Some(1);
        assert_eq!(aggregate_baseline_provenance(&cells2), "jrc_gfc2020_v3");

        // Neither baseline anywhere → neither_available.
        let none_cells = vec![EudrCellVerdict {
            cell: "c0".into(),
            verdict: 4,
            label: "indeterminate",
            jrc_forest_2020: None,
            hansen_treecover_2000: None,
            hansen_lossyear: None,
            jrc_tmf_deforestation_year: None,
            wri_driver_class: None,
            radd_alert_date: None,
            refinement_applied: Some("no_baseline_input"),
            borderline_canopy: false,
            fact_cids: vec![],
            lossyear_fact_cid: None,
        }];
        assert_eq!(
            aggregate_baseline_provenance(&none_cells),
            "neither_available"
        );
    }

    #[test]
    fn eudr_verdict_expects_calendar_lossyear_not_raw_byte() {
        // The verdict compares `hansen_ly > cutoff_year` with cutoff_year a
        // CALENDAR year (2020). Both materializer paths must therefore emit
        // the Hansen lossyear as a calendar year (2000 + byte), not the raw
        // 1..24 byte. This test pins the invariant and documents the
        // false-pass the raw byte caused in the default batched path.
        let cutoff = 2020i64;
        // forest in 2020 (jrc=1), cleared in 2022 → MUST fail (code 2).
        let (verdict_calendar, _) =
            eudr_verdict_for(Some(1), Some(80), Some(2022), None, None, None, cutoff);
        assert_eq!(
            verdict_calendar, 2,
            "2022 clearing of 2020-forest must FAIL"
        );

        // The OLD bug: the same clearing stored as the raw byte 22. `22 > 2020`
        // is false, so the loss is missed and the cell PASSES, the exact
        // false-pass the decode fix removes. We assert it does NOT fail, to
        // prove the bug was real and that storing bytes is unsafe.
        let (verdict_byte_bug, _) =
            eudr_verdict_for(Some(1), Some(80), Some(22), None, None, None, cutoff);
        assert_ne!(
            verdict_byte_bug, 2,
            "raw-byte lossyear (22) silently false-PASSES a 2022 clearing, \
             the bug the batched-path decode fix closes"
        );

        // Pre-cut-off clearing (2008, calendar) → not_in_scope (code 3),
        // never pass: the cell was not forest at the 2020 cut-off.
        let (verdict_old_loss, _) =
            eudr_verdict_for(None, Some(80), Some(2008), None, None, None, cutoff);
        assert_eq!(
            verdict_old_loss, 3,
            "2008 clearing → not_in_scope at a 2020 cut-off"
        );
    }

    #[test]
    fn lossyear_tally_counts_years_cutoff_and_parents() {
        // Build a sampled plot: two cells lost in 2022, one in 2018, one
        // with no loss (0), one with no reading (None). Cutoff year 2020.
        let mk = |cell: &str, ly: Option<i64>, cid: Option<&str>| EudrCellVerdict {
            cell: cell.into(),
            verdict: 1,
            label: "pass",
            jrc_forest_2020: Some(1),
            hansen_treecover_2000: Some(80),
            hansen_lossyear: ly,
            jrc_tmf_deforestation_year: None,
            wri_driver_class: None,
            radd_alert_date: None,
            refinement_applied: None,
            borderline_canopy: false,
            fact_cids: vec![],
            lossyear_fact_cid: cid.map(String::from),
        };
        let per_cell = vec![
            mk("c0", Some(2022), Some("ly-a")),
            mk("c1", Some(2022), Some("ly-b")),
            mk("c2", Some(2018), Some("ly-c")),
            mk("c3", Some(0), Some("ly-d")),
            mk("c4", None, None),
        ];
        let t = compute_lossyear_tally(&per_cell, 2020, 1024);
        // by_year ascending, only loss years.
        assert_eq!(t.by_year, vec![(2018, 1), (2022, 2)]);
        // 2022 > 2020 cutoff (×2); 2018 <= 2020 → not after-cutoff.
        assert_eq!(t.after_cutoff_cells, 2);
        assert_eq!(t.no_loss_cells, 1);
        assert_eq!(t.unknown_cells, 1);
        assert_eq!(t.total_sampled_cells, 5);
        // Parents = the 4 distinct lossyear CIDs (c4 had none), sorted.
        assert_eq!(t.parents, vec!["ly-a", "ly-b", "ly-c", "ly-d"]);
        assert!(!t.parents_capped);

        // Cap fires and is disclosed; total stays authoritative.
        let capped = compute_lossyear_tally(&per_cell, 2020, 2);
        assert_eq!(capped.parents.len(), 2);
        assert!(capped.parents_capped);
        assert_eq!(capped.total_sampled_cells, 5);
    }

    /// The three GPU-sidecar foundation embeddings (`prithvi_eo2`,
    /// `clay_v1`, `galileo`) must all be reachable through the same
    /// materializer registry path that `recall_with_auto_materialize`
    /// uses to fan out: `band_materializer_meta(band).is_some()` AND
    /// the band is enumerated in `all_materializable_bands()`. If
    /// either side regresses, agents calling
    /// `recall(band=clay_v1)` on a fresh cell silently get empty
    /// instead of an embedding (the materializer dispatch never fires)
    ///, exactly the bug this PR is fixing.
    #[test]
    fn foundation_bands_appear_in_materializer_registry() {
        let listed: std::collections::HashSet<String> =
            all_materializable_bands().into_iter().collect();
        for band in ["prithvi_eo2", "clay_v1", "galileo"] {
            assert!(
                listed.contains(band),
                "all_materializable_bands() is missing `{band}`, recall_with_auto_materialize \
                 won't surface it under /v1/materializers"
            );
            assert!(
                band_materializer_meta(band).is_some(),
                "band_materializer_meta(\"{band}\") returned None, the materializer is \
                 not wired into the dispatch table; recall on a fresh cell will silently \
                 return empty instead of auto-materialising"
            );
            // Every foundation embedding must declare its upstream wire
            // path so /v1/materializers + /v1/coverage_matrix surface
            // the chip-fetcher + sidecar route a verifier can reproduce.
            let meta = band_materializer_meta(band).unwrap();
            assert!(
                meta.wire_path.contains("emem-jepa-sidecar"),
                "{band}.wire_path = {:?} must mention emem-jepa-sidecar so agents know which \
                 compute tier produced the embedding",
                meta.wire_path
            );
        }
    }

    /// `FOUNDATION_ENCODERS` is the default fan-out list for
    /// `/v1/state_multi`. It MUST stay aligned with the live
    /// materialiser-bearing foundation embeddings so the multi-encoder
    /// state vector covers every wired model, never one less, never
    /// one more (so agents don't get a never-materialising encoder
    /// like `clay_v1` was historically reported as).
    #[test]
    fn foundation_encoders_includes_every_live_foundation_band() {
        for band in ["geotessera", "clay_v1", "prithvi_eo2", "galileo"] {
            assert!(
                FOUNDATION_ENCODERS.contains(&band),
                "FOUNDATION_ENCODERS missing `{band}`, /v1/state_multi default fan-out \
                 would skip it"
            );
        }
    }

    /// The bands manifest must carry a `galileo` entry under the
    /// `foundation` family, without it `/v1/bands` doesn't surface
    /// Galileo as a discoverable encoder and agents can't see the
    /// cube-slot offset for layout introspection.
    #[test]
    fn galileo_band_present_in_bands_registry() {
        let reg = &*emem_core::bands::DEFAULT;
        let galileo = reg
            .lookup("galileo")
            .expect("galileo band not in bands-v0.json manifest");
        assert!(
            matches!(galileo.family, emem_core::bands::BandFamily::Foundation),
            "galileo band must be family=foundation (got {:?})",
            galileo.family
        );
        // 48 dims at offset 1701, carved from the historic 91-dim
        // reserved tail. If a future PR expands the slot, this is the
        // canary that catches a misaligned offset.
        assert_eq!(galileo.dims, 48, "galileo cube slot allocates 48 dims");
        assert_eq!(galileo.offset, 1701, "galileo cube slot at offset 1701");
    }

    // ── Memory-substrate primitives (Part 1/2/3 of the substrate
    //    upgrade) ────────────────────────────────────────────────────

    /// Spin an in-process ephemeral responder so tokio-based tests can
    /// exercise sled-persisted memory-tool / memory-bundle endpoints
    /// without a network round-trip. Mirrors the construction used in
    /// `emem-server`, minus the long-running router warmup.
    /// data_availability compact projection: the MCP wire
    /// path must return a lean per-band shape so the ~122-band array is not
    /// truncated. Assert compact drops the prose fields and full keeps them,
    /// over the same band set.
    #[test]
    fn data_availability_compact_drops_prose_keeps_bands() {
        let s = test_app_state();
        let full = data_availability_json(&s, false);
        let compact = data_availability_json(&s, true);
        let fe = full["entries"].as_array().unwrap();
        let ce = compact["entries"].as_array().unwrap();
        assert_eq!(fe.len(), ce.len(), "same band set in both projections");
        assert!(!fe.is_empty(), "there are materializable bands");
        // Full carries per-band prose; compact does not.
        assert!(fe[0].get("upstream_wire_path").is_some());
        assert!(ce[0].get("upstream_wire_path").is_none());
        assert!(ce[0].get("history_available_from_iso").is_none());
        // Compact keeps the load-bearing fields.
        for k in ["band", "kind", "tempo", "backfill_supported"] {
            assert!(ce[0].get(k).is_some(), "compact keeps {k}");
        }
        assert_eq!(compact["projection"], json!("compact"));
        // Compact is materially smaller on the wire.
        let fs = serde_json::to_string(&full).unwrap().len();
        let cs = serde_json::to_string(&compact).unwrap().len();
        assert!(
            cs * 2 < fs,
            "compact should be well under half the full size ({cs} vs {fs})"
        );
    }

    pub(crate) fn test_app_state() -> AppState {
        use emem_storage::server::{ManifestCids, ResponderIdentity};
        use emem_storage::{MaterializingStorage, Server};
        let bands = std::sync::Arc::new((*emem_core::bands::DEFAULT).clone());
        let functions = std::sync::Arc::new((*emem_core::functions::DEFAULT).clone());
        let sources = std::sync::Arc::new((*emem_core::sources::DEFAULT).clone());
        let storage =
            MaterializingStorage::ephemeral(bands, functions, sources).expect("ephemeral storage");
        let identity = ResponderIdentity::fresh();
        let manifests = ManifestCids {
            registry_cid: emem_fact::RegistryCid::new("reg".to_string()),
            schema_cid: emem_fact::SchemaCid::new("sch".to_string()),
            bands_cid: "bands".to_string(),
            sources_cid: "sources".to_string(),
        };
        std::sync::Arc::new(Server {
            storage: std::sync::Arc::new(storage),
            identity,
            manifests,
            started_at_unix_s: 0,
        })
    }

    /// The delivery hole, pinned. Three notes addressed to named agents in
    /// the body, under a headline with no arrow, were filed as private
    /// journals and delivered to nobody. Found by checking whether mail
    /// arrived rather than assuming it had.
    #[test]
    fn a_note_that_names_its_recipients_in_the_body_is_delivered() {
        let body = "# WS-H and WS-E are built, and the suite found a 413\n\n                    From attester `k572x7go` (`k572x7go72uoih45j2xnvaoznda7jem`), 2026-08-06.\n                    To `u4aaoieq`, `sgozfgkr`, cc `hvev7m7n`, `6ww7pxav`.\n\n                    Body follows.";
        let (direct, cc, broadcast) = parse_note_addressing(body);
        assert_eq!(direct, vec!["u4aaoieq", "sgozfgkr"]);
        assert_eq!(cc, vec!["hvev7m7n", "6ww7pxav"]);
        assert!(!broadcast, "naming recipients is not a broadcast");
    }

    /// The arrow convention still works and still wins, so nothing that was
    /// being delivered stops being delivered.
    #[test]
    fn the_arrow_heading_still_addresses_and_takes_precedence() {
        let body = "# k572x7go -> sgozfgkr (cc u4aaoieq): the parity gate\n\n                    To `somebody-else-entirely`\n";
        let (direct, cc, _) = parse_note_addressing(body);
        assert_eq!(direct, vec!["sgozfgkr"]);
        assert_eq!(cc, vec!["u4aaoieq"]);
    }

    /// The reason this was not just "deliver anything with a To in it": an
    /// inbox that fills with journals is an inbox nobody reads, which is the
    /// failure this endpoint was built to fix in the first place.
    #[test]
    fn prose_and_journals_are_still_not_mail() {
        for body in [
            // Ordinary prose beginning with the word.
            "# a design note\n\nTo make this work we had to rewrite the parser.\n",
            // A To line naming nothing addressable.
            "# a draft\n\nTo: the reader, whoever that turns out to be\n",
            // A mention far below the top of the note.
            &format!(
                "# a long note\n\n{}\nTo `u4aaoieq`\n",
                "filler\n".repeat(30)
            ),
            // No arrow, no To line: a private journal entry.
            "# state dump 2026-08-06\n\nnumbers follow\n",
        ] {
            let (direct, cc, broadcast) = parse_note_addressing(body);
            assert!(
                direct.is_empty() && cc.is_empty() && !broadcast,
                "delivered something that is not mail: {body:?} -> {direct:?} {cc:?} {broadcast}"
            );
        }
    }

    /// An agent key is 8 characters of lowercase base32, and that shape is
    /// the whole discriminator that makes reading a To line safe.
    #[test]
    fn only_agent_shaped_tokens_can_address_a_note() {
        assert!(looks_like_agent_key("u4aaoieq"));
        assert!(looks_like_agent_key("`sgozfgkr`"));
        for bad in [
            "u4aaoieq1", // too long
            "u4aaoie",   // too short
            "U4AAOIEQ",  // uppercase is not the address form
            "u4aaoie8",  // 8 and 9 are not in base32
            "the-agent",
            "",
        ] {
            assert!(!looks_like_agent_key(bad), "{bad} should not address");
        }
    }

    /// The hosted guard route, through the real handler and real storage.
    ///
    /// The property that matters most is the one an agent would get wrong on
    /// its own: a citation this responder does not hold is an ALLOW. It is
    /// indistinguishable from one minted by another responder, and denying on
    /// it would punish an agent for citing across nodes, which is the exact
    /// behaviour the token format exists to enable.
    #[tokio::test]
    async fn the_hosted_guard_allows_a_citation_it_does_not_hold() {
        let s = test_app_state();
        let v = guard_verdict_json(
            &s,
            &json!({"texts":["per emem:fact:damO.zb000.xUti.zde78:wbqyxljmeewr7z4cav7guwf4qvsiwf2crv7w3272mgtvxgyn6m5q it is 918 m"]}),
        )
        .await;
        assert_eq!(v["action"], "allow");
        assert_eq!(v["checked"], 1, "it was still examined");
        assert_eq!(v["citations_found"], 1);
        // And it says out loud that it is not in anybody's request path.
        assert_eq!(v["advisory"], true);
        assert_eq!(v["schema"], "emem.guard.verdict.v1");
        // No leaf, because this responder keeps no verdict log. What it can
        // prove is what it read to decide, and the receipt is that: it names
        // nothing here, since the fact was not held.
        assert!(v["leaf"].is_null(), "an advisory verdict has no log entry");
        assert!(
            v["receipt"]["signature"].is_array() || v["receipt"]["sig_b32"].is_string(),
            "a verdict must still carry a signed statement of what was read"
        );
        assert_eq!(v["receipt"]["primitive"], "emem.guard.verdict");
        assert_eq!(
            v["receipt"]["fact_cids"].as_array().unwrap().len(),
            0,
            "nothing was resolvable, so the receipt claims nothing was read"
        );
    }

    /// Claim gating is per-call here rather than per-node, because the caller
    /// is the only person an advisory verdict affects. Off unless asked for.
    #[tokio::test]
    async fn the_hosted_guard_gates_claims_only_when_the_caller_asks() {
        let s = test_app_state();
        let body = json!({"texts":["Canopy height in Sumatra reached 31 m on 2026-08-05."]});

        let off = guard_verdict_json(&s, &body).await;
        assert_eq!(off["action"], "allow");
        assert!(off["code"].is_null(), "no rule fires by default");

        let mut on = body.clone();
        on["claim_gating"] = json!(true);
        let v = guard_verdict_json(&s, &on).await;
        assert_eq!(v["action"], "deny");
        assert_eq!(v["code"], "CLAIM_UNGROUNDED");
        assert_eq!(v["fix"], "cite_observation");
        // The actionable half: which band would answer this, so the remedy is
        // "resolve elevation there and cite it" rather than "cite something".
        // It must name a key recall will serve. `dem` is a family root and
        // answers `unknown_band`, so an agent that followed it went nowhere.
        assert_eq!(v["claim"]["source_band"], "copdem30m.elevation_mean");
        assert_eq!(v["claim"]["magnitude"], "31 m");

        // A citation this node cannot resolve does NOT buy an allow. Before
        // 2026-08-08 it did, so appending any well-formed token silenced the
        // denial the sentence had earned while `receipt.fact_cids` stayed
        // empty: defeating the gate was cheaper than satisfying it.
        let unresolvable = json!({
            "texts":["Canopy height in Sumatra reached 31 m on 2026-08-05, per emem:entity:abc123."],
            "claim_gating": true
        });
        let u = guard_verdict_json(&s, &unresolvable).await;
        assert_eq!(
            u["action"], "deny",
            "an unresolvable token is not grounding"
        );
        assert_eq!(u["code"], "CLAIM_UNGROUNDED");
        // And it is still not accused of being a forgery: no provenance code
        // fires on a token another responder may legitimately hold.
        assert_eq!(
            u["receipt"]["fact_cids"].as_array().map(|a| a.len()),
            Some(0)
        );
    }

    /// The gap a reader actually stood in: we published a nine-route table
    /// and seven of them answered 404 on this origin.
    ///
    /// Each hosted alias must reach the SAME verdict as the canonical route on
    /// the same input. They re-wrap the one engine and change the envelope,
    /// never the decision; an alias that diverged would be a second
    /// implementation nobody meant to write.
    #[tokio::test]
    async fn every_hosted_alias_agrees_with_the_canonical_route() {
        let s = test_app_state();
        let text = "Elevation there is 918 m per emem:fact:damO.zb000.xUti.zde78:wbqyxljmeewr7z4cav7guwf4qvsiwf2crv7w3272mgtvxgyn6m5q";
        let canonical = guard_verdict_json(&s, &json!({ "texts": [text] })).await;

        let bodies: [(GuardShape, JsonValue); 5] = [
            (GuardShape::Native, json!({ "texts": [text] })),
            (
                GuardShape::Mcp,
                json!({"method":"tools/call","params":{"name":"t","arguments":{"q":text}}}),
            ),
            (GuardShape::Openai, json!({ "input": text })),
            (
                GuardShape::Cloudevent,
                json!({"specversion":"1.0","id":"e1","data":{"t":text}}),
            ),
            (GuardShape::Policy, json!({"input":{"prompt":text}})),
        ];
        for (shape, body) in bodies {
            let v = guard_verdict_shaped(&s, &body, shape, None).await;
            // The decision, the count and what was found are the verdict. The
            // envelope around them is allowed to differ; that is the point.
            assert_eq!(v["checked"], canonical["checked"], "{shape:?}");
            assert_eq!(
                v["citations_found"], canonical["citations_found"],
                "{shape:?}"
            );
            assert_eq!(v["advisory"], true, "{shape:?} must stay advisory");
        }
    }

    /// The routes this responder cannot honestly serve must say WHY, not 404.
    /// An agent that cannot tell "not here" from "nowhere" gives up on both.
    /// Zero is never reported as a count, and never as clear.
    ///
    /// About 40% of readings across the camera fleet are zero, and the rate
    /// barely moves between 3am and the morning peak — if those were empty
    /// streets the number would collapse at rush hour. So a large share are
    /// frames the detector could not read, and nothing in the data separates
    /// them from a genuinely clear road.
    ///
    /// A robot reading {car: 0} as permission to move is the worst outcome
    /// this responder could cause, and every other property of that answer
    /// would still check out: signed, verifiable, and wrong.
    #[test]
    fn a_zero_detection_total_is_unobserved_and_says_not_to_move() {
        let (obs, warn) = robotics_observation(0);
        assert_eq!(obs, "unreadable_or_empty", "zero must not read as a count");
        assert!(warn.contains("Do not move on this"), "{warn}");
        assert!(
            warn.contains("unreadable frame"),
            "the warning must say WHY zero is not emptiness: {warn}"
        );

        // Control: a real reading is described as one, or the test above would
        // pass just as well if every answer refused.
        let (obs, warn) = robotics_observation(1);
        assert_eq!(obs, "objects_detected");
        assert!(!warn.contains("Do not move"), "{warn}");
    }

    #[tokio::test]
    async fn the_routes_a_shared_responder_cannot_serve_name_the_reason() {
        for (label, resp) in [
            ("vendor hook", hosted_needs_own_node().await),
            ("verdict log", hosted_no_verdict_log().await),
            ("modules", hosted_no_modules().await),
        ] {
            let status = resp.status();
            let bytes = axum::body::to_bytes(resp.into_body(), usize::MAX)
                .await
                .unwrap();
            let v: JsonValue = serde_json::from_slice(&bytes).unwrap();
            assert_eq!(status, StatusCode::NOT_IMPLEMENTED, "{label}");
            assert_eq!(v["schema"], "emem.error.v1", "{label}");
            // Every one points at the thing that CAN answer it.
            assert_eq!(v["selfhost"], "/v1/guard/selfhost", "{label}");
            assert!(
                v["message"].as_str().unwrap().len() > 80,
                "{label}: a refusal that does not explain is a 404 with extra steps"
            );
        }
    }

    /// The descriptor must describe THIS deployment, not a node in general.
    /// A hosted document claiming routes it does not serve is the same
    /// overclaim in a machine-readable form.
    #[tokio::test]
    async fn the_hosted_descriptor_only_claims_what_is_hosted() {
        let s = test_app_state();
        let Json(d) = hosted_guard_descriptor(State(s)).await;
        assert_eq!(d["deployment"], "hosted");
        assert_eq!(d["advisory"], true);
        assert_eq!(d["blocks_nothing"], true);

        let cps = d["checkpoints"].as_array().unwrap();
        let hosted: Vec<&str> = cps
            .iter()
            .filter(|c| c["hosted"] == true)
            .map(|c| c["route"].as_str().unwrap())
            .collect();
        assert_eq!(hosted.len(), 7, "seven routes run here: {hosted:?}");
        // The two that cannot run hosted say so AND say why.
        for c in cps.iter().filter(|c| c["hosted"] == false) {
            assert!(
                c["why"].as_str().is_some_and(|w| w.len() > 20),
                "{} claims not-hosted without a reason",
                c["route"]
            );
        }
        // And what is absent is named as absent rather than omitted.
        for k in ["/log/head", "/log/entries", "/modules"] {
            assert!(
                d["not_served_here"][k].is_string(),
                "{k} is silently missing rather than explained"
            );
        }
        assert_eq!(d["evidence_here"]["verify"], "/v1/verify_receipt");
    }

    /// A self-hosted node serves nine routes and this responder serves one.
    /// Without `?shape=` that difference would be a dialect: an agent that
    /// developed against `/verdict/mcp` locally could not point the same
    /// client here, and "run your own node" would be a prerequisite rather
    /// than an upgrade.
    #[tokio::test]
    async fn the_hosted_route_speaks_every_envelope_a_self_hosted_node_does() {
        let s = test_app_state();
        let cases: [(GuardShape, JsonValue, &str); 5] = [
            (
                GuardShape::Native,
                json!({"texts":["emem:fact:a:b"]}),
                "action",
            ),
            (
                GuardShape::Mcp,
                json!({"jsonrpc":"2.0","id":1,"method":"tools/call",
                       "params":{"name":"t","arguments":{"q":"emem:fact:a:b"}}}),
                "allow",
            ),
            (
                GuardShape::Openai,
                json!({"input":"emem:fact:a:b"}),
                "results",
            ),
            (
                GuardShape::Cloudevent,
                json!({"specversion":"1.0","id":"e1","type":"t","source":"/a",
                       "data":{"t":"emem:fact:a:b"}}),
                "type",
            ),
            (
                GuardShape::Policy,
                json!({"input":{"prompt":"emem:fact:a:b"}}),
                "result",
            ),
        ];
        for (shape, body, key) in cases {
            let v = guard_verdict_shaped(&s, &body, shape, None).await;
            assert!(
                v.get(key).is_some(),
                "{shape:?} did not answer in its own envelope: {v}"
            );
            // Whatever the envelope, the responder's own additions ride along
            // so a caller always knows what it is talking to.
            assert_eq!(v["advisory"], true, "{shape:?}");
            assert_eq!(v["schema"], "emem.guard.verdict.v1", "{shape:?}");
            assert!(
                v["receipt"]["primitive"] == "emem.guard.verdict",
                "{shape:?}"
            );
        }
    }

    /// Each shape has to actually READ its own body, not merely answer in its
    /// envelope. A shape that rendered correctly and scanned nothing would
    /// allow everything while looking like it worked.
    #[tokio::test]
    async fn every_shape_finds_the_citation_buried_in_its_own_body() {
        let s = test_app_state();
        let cid = "wbqyxljmeewr7z4cav7guwf4qvsiwf2crv7w3272mgtvxgyn6m5q";
        let tok = format!("emem:fact:damO.zb000.xUti.zde78:{cid}");
        let cases: [(GuardShape, JsonValue); 5] = [
            (GuardShape::Native, json!({ "texts": [tok] })),
            (
                GuardShape::Mcp,
                json!({"params":{"name":"t","result":{"content":[{"type":"text","text":tok}]}}}),
            ),
            (GuardShape::Openai, json!({ "input": [tok] })),
            (
                GuardShape::Cloudevent,
                json!({"specversion":"1.0","id":"e1","data":{"deep":{"nested":[tok]}}}),
            ),
            (GuardShape::Policy, json!({"input":{"turn":{"text":tok}}})),
        ];
        for (shape, body) in cases {
            let v = guard_verdict_shaped(&s, &body, shape, None).await;
            assert_eq!(
                v["citations_found"], 1,
                "{shape:?} did not read its own body: {v}"
            );
            assert_eq!(v["checked"], 1, "{shape:?}");
        }
    }

    /// An unrecognised shape reads the body as native rather than erroring,
    /// which is the same posture the verdict path takes everywhere else: a
    /// caller who mistyped still gets an answer.
    #[test]
    fn an_unknown_shape_falls_back_rather_than_failing() {
        assert_eq!(GuardShape::parse(None), GuardShape::Native);
        assert_eq!(GuardShape::parse(Some("banana")), GuardShape::Native);
        // The aliases people will actually type.
        assert_eq!(
            GuardShape::parse(Some("cloudevents")),
            GuardShape::Cloudevent
        );
        assert_eq!(GuardShape::parse(Some("opa")), GuardShape::Policy);
    }

    /// The body an agent posts here has to be the body it would post to a node
    /// it self-hosts. Learning one shape has to be enough, or the hosted route
    /// becomes a dialect.
    #[tokio::test]
    async fn the_hosted_route_accepts_the_same_shapes_a_self_hosted_node_does() {
        let s = test_app_state();
        for body in [
            json!({"texts":["hello"]}),
            json!({"messages":[{"role":"user","content":"hello"}]}),
            json!({"messages":[{"role":"assistant","content":[{"type":"text","text":"hello"}]}]}),
            // A framework that decorates must not break it.
            json!({"texts":["hello"],"framework":"langgraph","trace_id":"t1"}),
            // And nothing at all is answerable rather than an error.
            json!({}),
        ] {
            let v = guard_verdict_json(&s, &body).await;
            assert_eq!(v["action"], "allow", "{body}");
            assert!(v["advisory"].as_bool().unwrap(), "{body}");
        }
    }

    /// The self-host document is served, not described. An agent that can
    /// reach this responder can build its own node without a person handing
    /// it anything.
    #[tokio::test]
    async fn the_selfhost_skill_is_served_whole_and_runnable() {
        let Json(v) = get_guard_selfhost().await;
        let skill = v["skill"].as_str().expect("the skill is the payload");
        assert!(skill.len() > 4000, "truncated: {} bytes", skill.len());
        assert!(skill.starts_with("---"), "the frontmatter must survive");
        // Every command the response promises has to appear in the document
        // it ships, or the two drift and the agent follows the wrong one.
        for cmd in [
            "cargo build --release -p emem-guard",
            "cargo test --release -p emem-guard",
            "--responder",
            "--shadow",
            "--report",
            "--audit",
        ] {
            assert!(skill.contains(cmd), "the skill never mentions {cmd}");
        }
        assert!(v["run_bare"].is_string());
    }

    /// CORS advertised a header this server never sent.
    ///
    /// `mcp-protocol-version` sat in `access-control-expose-headers`, which
    /// tells a browser client the header is there to be read, while nothing
    /// ever set it. That is the same defect shape as a deny naming a band
    /// recall cannot serve: a published promise with no implementation behind
    /// it, where the caller who believes the contract is the one who suffers.
    #[tokio::test]
    async fn the_mcp_protocol_version_header_is_sent_and_an_unknown_one_is_refused() {
        use axum::http::{HeaderMap, HeaderValue, StatusCode};
        let s = test_app_state();
        let body = axum::body::Bytes::from(
            r#"{"jsonrpc":"2.0","id":1,"method":"tools/list","params":{}}"#,
        );

        // Absent: answered under the revision Streamable HTTP says to assume,
        // not under our newest, because omitting the header expresses no
        // intent to use it.
        let r = mcp_with_version(s.clone(), HeaderMap::new(), body.clone(), "core").await;
        assert_eq!(r.status(), StatusCode::OK);
        assert_eq!(
            r.headers().get("mcp-protocol-version").unwrap(),
            MCP_VERSION_WHEN_HEADER_ABSENT
        );

        // Present and supported: echoed, so the client can confirm which
        // revision it actually got rather than the one it hoped for.
        for v in MCP_SUPPORTED_VERSIONS {
            let mut h = HeaderMap::new();
            h.insert("mcp-protocol-version", HeaderValue::from_static(v));
            let r = mcp_with_version(s.clone(), h, body.clone(), "core").await;
            assert_eq!(r.status(), StatusCode::OK, "{v} must be served");
            assert_eq!(r.headers().get("mcp-protocol-version").unwrap(), *v);
        }

        // Present and impossible: refused, and the refusal names what we do
        // speak. Accepting it silently let a caller believe it had negotiated
        // something.
        let mut h = HeaderMap::new();
        h.insert(
            "mcp-protocol-version",
            HeaderValue::from_static("1999-01-01"),
        );
        let r = mcp_with_version(s.clone(), h, body, "core").await;
        assert_eq!(r.status(), StatusCode::BAD_REQUEST);
    }

    /// Every deny code and every remedy a verdict can carry is published, or
    /// an agent reading the contract meets one it was never told about.
    #[tokio::test]
    async fn the_guard_contract_covers_every_code_the_engine_can_emit() {
        let s = test_app_state();
        let v = guard_capabilities_json(&s);
        let codes: Vec<&str> = v["deny_codes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|c| c["code"].as_str().unwrap())
            .collect();
        // Exhaustive over the enum rather than a list someone remembers to
        // extend. PROV_VALUE shipped 2026-08-09 and this test passed without
        // it, because it only ever checked the codes already written down,
        // while its own name promised every code the engine can emit.
        for c in emem_guard::policy::DenyCode::ALL {
            assert!(
                codes.contains(&c.as_str()),
                "{} undocumented: an agent reading the contract would meet a \
                 code it was never told about",
                c.as_str()
            );
        }
        let fixes: Vec<&str> = v["fixes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|f| f["fix"].as_str().unwrap())
            .collect();
        for f in emem_guard::policy::Fix::ALL {
            assert!(fixes.contains(&f.as_str()), "{} undocumented", f.as_str());
        }
        assert_eq!(v["hosted"]["blocks_nothing"], true);
    }

    /// End-to-end through the REAL `/v1/verify_receipt` handler: a freshly
    /// signed receipt must verify `valid:true` and report the version the
    /// signer actually emits; flipping a cell must drop it to
    /// `valid:false`. Guards the signer↔verifier contract across the
    /// preimage cutovers — the version is read from the receipt rather
    /// than asserted as a literal, because pinning a literal here is what
    /// turns a deliberate version bump into a test failure that says
    /// nothing about correctness.
    #[tokio::test]
    async fn verify_receipt_roundtrip_and_tamper() {
        use std::time::Instant;
        let s = test_app_state();
        let receipt = s.sign_receipt(
            "emem.recall",
            vec!["damO.zb000.xUti.zde78".into()],
            vec![emem_fact::FactCid::new("fc-1")],
            true,
            Instant::now(),
            None,
        );
        assert_eq!(
            receipt.preimage_version,
            emem_attest::PREIMAGE_V2,
            "the signer emits v2; v1 receipts remain verifiable but are no longer minted"
        );

        // Genuine receipt → valid:true.
        let req = VerifyReceiptReq {
            receipt: receipt.clone(),
            pubkey_b32: None,
            current_responder_epoch: None,
            facts: None,
        };
        let Json(body) = post_verify_receipt(State(s.clone()), Ok(Json(req)))
            .await
            .expect("verify ok");
        assert_eq!(
            body["valid"],
            serde_json::json!(true),
            "genuine v1 receipt must verify: {body}"
        );
        assert_eq!(
            body["preimage_version"],
            serde_json::json!(receipt.preimage_version),
            "the verifier must report the receipt's own version, not a constant"
        );

        // Tampered receipt (cell swapped after signing) → valid:false.
        let mut tampered = receipt;
        tampered.cells = vec!["damO.zzzzz.xUti.zde78".into()];
        let req2 = VerifyReceiptReq {
            receipt: tampered,
            pubkey_b32: None,
            current_responder_epoch: None,
            facts: None,
        };
        let Json(body2) = post_verify_receipt(State(s), Ok(Json(req2)))
            .await
            .expect("verify call ok");
        assert_eq!(
            body2["valid"],
            serde_json::json!(false),
            "tampered receipt must NOT verify"
        );
    }

    /// Stripping the inclusion proof must be detected by the REAL handler.
    ///
    /// This is the audit's downgrade-by-removal finding, end to end. Under
    /// v1 the signature did not cover `merkle_proof`, so deleting it left
    /// `valid: true` with `merkle_proof_valid: null` and no trace. The v2
    /// binding signs "here is my proof" or "I have none", so rewriting one
    /// into the other breaks the signature.
    #[tokio::test]
    async fn verify_receipt_detects_stripped_or_forged_proof() {
        use std::time::Instant;
        let s = test_app_state();
        let receipt = s.sign_receipt(
            "emem.recall",
            vec!["damO.zb000.xUti.zde78".into()],
            vec![emem_fact::FactCid::new("fc-1")],
            true,
            Instant::now(),
            None,
        );

        // Rewrite the proof field in whichever direction this fixture
        // allows: strip it if present, forge one if absent. Both are the
        // same binding read from opposite sides, and asserting only the
        // strip case would silently pass on a fixture with no tree.
        let mut rewritten = receipt.clone();
        rewritten.merkle_proof = match receipt.merkle_proof.clone() {
            Some(_) => None,
            None => Some(emem_fact::MerkleProof {
                leaf_index: 0,
                path: vec![[7u8; 32]],
                root: [9u8; 32],
                version: 1,
            }),
        };

        let req = VerifyReceiptReq {
            receipt: rewritten,
            pubkey_b32: None,
            current_responder_epoch: None,
            facts: None,
        };
        let Json(body) = post_verify_receipt(State(s), Ok(Json(req)))
            .await
            .expect("verify call ok");
        assert_eq!(
            body["valid"],
            serde_json::json!(false),
            "rewriting merkle_proof under v2 must invalidate the receipt: {body}"
        );
        assert_eq!(
            body["signature_valid"],
            serde_json::json!(false),
            "the SIGNATURE must fail, not merely the proof walk — that is what \
             makes stripping detectable rather than just reportable"
        );
    }

    /// A LEGACY v0 receipt (no preimage_version) must still verify
    /// `valid:true` through the same handler, back-compat guard.
    #[tokio::test]
    async fn verify_receipt_v0_legacy_still_verifies() {
        let s = test_app_state();
        // Hand-build a v0 receipt and sign it under the legacy preimage
        // (request_id|served_at|manifest?|primitive|cells,|cids,).
        let request_id = "01J0V0RIDLEGACY00000000000".to_string();
        let served_at = "2026-06-01T00:00:00Z".to_string();
        let primitive = "emem.recall";
        let cells = vec!["damO.zb000.xUti.zde78".to_string()];
        let fact_cids = vec![emem_fact::FactCid::new("fc-legacy")];
        // No source_versions → no manifest segment (matches pre-F3 receipts).
        let mut h = blake3::Hasher::new();
        h.update(request_id.as_bytes());
        h.update(b"|");
        h.update(served_at.as_bytes());
        h.update(b"|");
        h.update(primitive.as_bytes());
        h.update(b"|");
        for c in &cells {
            h.update(c.as_bytes());
            h.update(b",");
        }
        h.update(b"|");
        for c in &fact_cids {
            h.update(c.as_str().as_bytes());
            h.update(b",");
        }
        let msg = h.finalize();
        let sig = s.identity.signing.sign(msg.as_bytes());
        let mut sig_bytes = [0u8; 64];
        sig_bytes.copy_from_slice(&sig.to_bytes());

        let receipt = emem_fact::Receipt {
            request_id,
            served_at,
            primitive: primitive.into(),
            intent: None,
            // Empty on purpose: this fixture hand-builds a LEGACY receipt,
            // and a legacy payload carried neither field. They skip when
            // empty, so it round-trips byte-identically to what a v0
            // verifier saw.
            responder_pubkey_b32: String::new(),
            signature_b32: String::new(),
            cells,
            fact_cids,
            schema_cid: emem_fact::SchemaCid::new("sch"),
            merkle_proof: None,
            responder: s.identity.pubkey,
            responder_key_epoch: s.identity.epoch,
            signature: emem_core::Signature(sig_bytes),
            source_versions: std::collections::BTreeMap::new(),
            registry_cid: emem_fact::RegistryCid::new("reg"),
            cost: emem_fact::Cost {
                credits: 0,
                latency_p50_ms: 0,
                latency_p99_ms: 0,
                source_freshness_s: None,
                was_cached: true,
            },
            as_of: None,
            field: None,
            scope: None,
            edge_cids: Vec::new(),
            preimage_version: 0,
        };
        let req = VerifyReceiptReq {
            receipt,
            pubkey_b32: None,
            current_responder_epoch: None,
            facts: None,
        };
        let Json(body) = post_verify_receipt(State(s), Ok(Json(req)))
            .await
            .expect("verify ok");
        assert_eq!(
            body["valid"],
            serde_json::json!(true),
            "legacy v0 receipt must still verify: {body}"
        );
        assert_eq!(body["preimage_version"], serde_json::json!(0));
    }

