    #[test]
    fn memory_path_rejects_traversal() {
        // The Anthropic memory tool root is `/memories/`. Anything
        // that tries to climb out (`..`, paths outside the prefix, NUL)
        // must fail BEFORE we touch storage.
        for bad in &[
            "../etc/passwd",
            "/etc/passwd",
            "/memories/../etc/passwd",
            "/memories/sub/../../etc",
            "/memories/./hidden",
            "memories/foo", // no leading slash
            "/memories",    // no trailing slash AND no name
            "/memories/foo\0bar",
            "/memories//double",
        ] {
            assert!(
                validate_memory_path(bad, /*allow_directory=*/ true).is_err(),
                "validate_memory_path must reject `{bad}`"
            );
        }
        for good in &[
            "/memories/foo.md",
            "/memories/sub/foo.md",
            "/memories/deep/nested/file.txt",
        ] {
            assert!(
                validate_memory_path(good, false).is_ok(),
                "validate_memory_path must accept `{good}`"
            );
        }
        // Directory listing requires the trailing slash.
        assert!(validate_memory_path("/memories/", true).is_ok());
        assert!(validate_memory_path("/memories/", false).is_err());
    }

    #[test]
    fn witness_preimage_signs_and_verifies() {
        use ed25519_dalek::{Signer, SigningKey};
        let sk = SigningKey::from_bytes(&[7u8; 32]);
        let pk = sk.verifying_key();
        let pk_bytes: [u8; 32] = pk.to_bytes();
        let root = [0x11u8; 32];
        let tree_size = 12_345u64;
        let preimage = witness_preimage(tree_size, &root, &pk_bytes);
        let sig = sk.sign(&preimage);
        assert!(pk.verify_strict(&preimage, &sig).is_ok());
        // A different root (equivocation) yields a different preimage, so
        // the co-signature no longer verifies, the binding is to the exact
        // (tree_size, root) pair.
        let forked = witness_preimage(tree_size, &[0x22u8; 32], &pk_bytes);
        assert!(pk.verify_strict(&forked, &sig).is_err());
        // A different tree_size likewise breaks it.
        let resized = witness_preimage(tree_size + 1, &root, &pk_bytes);
        assert!(pk.verify_strict(&resized, &sig).is_err());
        // base32 helper round-trips and rejects malformed input.
        let b32 = data_encoding::BASE32_NOPAD.encode(&pk_bytes).to_lowercase();
        assert_eq!(b32_decode_n::<32>(&b32), Some(pk_bytes));
        assert!(b32_decode_n::<32>("not-valid-base32!").is_none());
        assert!(b32_decode_n::<64>(&b32).is_none()); // wrong length
    }

    #[test]
    fn memory_write_policy_gates_the_right_verbs() {
        use MemoryWritePolicy::*;
        let verbs = ["create", "str_replace", "insert", "delete", "rename"];
        // Open: nothing on the open namespace needs an attester (default;
        // preserves Anthropic memory-tool compatibility).
        for v in verbs {
            assert!(!policy_gates_verb(Open, v), "Open must not gate `{v}`");
        }
        // HardenDestructive: only delete/rename are gated; append-style
        // writes stay open.
        assert!(!policy_gates_verb(HardenDestructive, "create"));
        assert!(!policy_gates_verb(HardenDestructive, "str_replace"));
        assert!(!policy_gates_verb(HardenDestructive, "insert"));
        assert!(policy_gates_verb(HardenDestructive, "delete"));
        assert!(policy_gates_verb(HardenDestructive, "rename"));
        // RequireAll: every verb is gated.
        for v in verbs {
            assert!(
                policy_gates_verb(RequireAll, v),
                "RequireAll must gate `{v}`"
            );
        }
    }

