    /// The per-attester write backstop bounds a runaway loop without a human
    /// gate. Test the burst cap and per-key isolation deterministically with
    /// `per_sec: 0.0` (no refill), and confirm the `off` switch never denies.
    #[test]
    fn write_rate_limiter_bounds_burst_per_key_and_honours_disable() {
        // enabled, capacity 3, no refill → first 3 pass, 4th is denied.
        let l = WriteRateLimiter {
            buckets: std::sync::Mutex::new(std::collections::HashMap::new()),
            per_sec: 0.0,
            burst: 3.0,
            enabled: true,
        };
        assert!(l.check("agentA").is_ok());
        assert!(l.check("agentA").is_ok());
        assert!(l.check("agentA").is_ok());
        let denied = l.check("agentA");
        assert!(denied.is_err(), "4th write past the burst must be denied");
        assert!(
            denied.unwrap_err() >= 1,
            "retry hint is a whole positive second"
        );
        // A different identity has its own bucket, one flood never starves
        // another agent.
        assert!(l.check("agentB").is_ok());

        // The disable switch is an operator escape hatch: never denies.
        let off = WriteRateLimiter {
            buckets: std::sync::Mutex::new(std::collections::HashMap::new()),
            per_sec: 0.0,
            burst: 1.0,
            enabled: false,
        };
        assert!(off.check("k").is_ok());
        assert!(off.check("k").is_ok());
        assert!(off.check("k").is_ok());
    }

    #[tokio::test]
    async fn memory_file_create_view_replace_insert_delete_roundtrip() {
        let s = test_app_state();
        // Create.
        let create = memory_create_inner(
            &s,
            MemoryCreateReq {
                path: "/memories/notes.md".into(),
                file_text: "hello world".into(),
                kind: None,
                attester: None,
            },
        )
        .await
        .map_err(|e| format!("create: {} {}", e.0, e.1.message))
        .unwrap();
        let cid1 = create
            .get("file_cid")
            .and_then(|v| v.as_str())
            .expect("file_cid")
            .to_string();
        assert!(!cid1.is_empty());

        // View.
        let view = memory_view_inner(
            &s,
            MemoryViewReq {
                path: "/memories/notes.md".into(),
                offset: None,
                view_range: None,
                kind: None,
                vault_capability: None,
            },
        )
        .await
        .map_err(|e| format!("view: {} {}", e.0, e.1.message))
        .unwrap();
        assert_eq!(
            view.get("content").and_then(|v| v.as_str()),
            Some("hello world")
        );

        // str_replace produces a new file_cid.
        let rep = memory_str_replace_inner(
            &s,
            MemoryStrReplaceReq {
                path: "/memories/notes.md".into(),
                old_str: "hello".into(),
                new_str: "hi".into(),
                kind: None,
                attester: None,
            },
        )
        .await
        .map_err(|e| format!("str_replace: {} {}", e.0, e.1.message))
        .unwrap();
        let cid2 = rep
            .get("file_cid")
            .and_then(|v| v.as_str())
            .expect("file_cid")
            .to_string();
        assert_ne!(cid1, cid2, "str_replace must produce a fresh file_cid");

        let view2 = memory_view_inner(
            &s,
            MemoryViewReq {
                path: "/memories/notes.md".into(),
                offset: None,
                view_range: None,
                kind: None,
                vault_capability: None,
            },
        )
        .await
        .map_err(|e| format!("view2: {} {}", e.0, e.1.message))
        .unwrap();
        assert_eq!(
            view2.get("content").and_then(|v| v.as_str()),
            Some("hi world")
        );

        // insert prepends at line 0.
        let _ins = memory_insert_inner(
            &s,
            MemoryInsertReq {
                path: "/memories/notes.md".into(),
                insert_line: 0,
                new_str: "header".into(),
                kind: None,
                attester: None,
            },
        )
        .await
        .map_err(|e| format!("insert: {} {}", e.0, e.1.message))
        .unwrap();
        let view3 = memory_view_inner(
            &s,
            MemoryViewReq {
                path: "/memories/notes.md".into(),
                offset: None,
                view_range: None,
                kind: None,
                vault_capability: None,
            },
        )
        .await
        .map_err(|e| format!("view3: {} {}", e.0, e.1.message))
        .unwrap();
        let text3 = view3
            .get("content")
            .and_then(|v| v.as_str())
            .unwrap_or_default();
        assert!(
            text3.starts_with("header\n"),
            "expected insert at top; got {text3:?}"
        );

        // delete drops the file.
        let del = memory_delete_inner(
            &s,
            MemoryDeleteReq {
                path: "/memories/notes.md".into(),
                attester: None,
            },
        )
        .await
        .map_err(|e| format!("delete: {} {}", e.0, e.1.message))
        .unwrap();
        assert_eq!(del.get("ok").and_then(|v| v.as_bool()), Some(true));
        let viewmiss = memory_view_inner(
            &s,
            MemoryViewReq {
                path: "/memories/notes.md".into(),
                offset: None,
                view_range: None,
                kind: None,
                vault_capability: None,
            },
        )
        .await;
        assert!(viewmiss.is_err(), "view must 404 after delete");
    }

    #[tokio::test]
    async fn memory_file_receipt_verifies_offline() {
        // Every write returns a Receipt that the existing
        // /v1/verify_receipt path validates without any new code.
        let s = test_app_state();
        let resp = memory_create_inner(
            &s,
            MemoryCreateReq {
                path: "/memories/verify.md".into(),
                file_text: "audit me".into(),
                kind: None,
                attester: None,
            },
        )
        .await
        .map_err(|e| format!("create: {} {}", e.0, e.1.message))
        .unwrap();
        let receipt_json = resp.get("receipt").cloned().expect("receipt");
        let receipt: emem_fact::Receipt =
            serde_json::from_value(receipt_json).expect("receipt deserialises");
        let req = VerifyReceiptReq {
            receipt,
            pubkey_b32: None,
            current_responder_epoch: None,
            facts: None,
        };
        let v = post_verify_receipt(State(s.clone()), Ok(Json(req)))
            .await
            .map_err(|e| format!("verify ok: {} {}", e.0, e.1.message))
            .unwrap();
        assert_eq!(
            v.get("valid").and_then(|x| x.as_bool()),
            Some(true),
            "memory-file receipt must verify against the responder pubkey: {v:?}"
        );

        // Regression (2026-05-31 trust fix): a genuine receipt presented
        // alongside a fact it does NOT attest must NOT verify. Pre-fix the
        // `facts` field was dropped by serde and a doctored fact returned
        // `valid:true`. Build a fact whose CID can't be in this receipt.
        let receipt2: emem_fact::Receipt =
            serde_json::from_value(resp.get("receipt").cloned().expect("receipt"))
                .expect("receipt deserialises");
        let bogus = emem_fact::Fact::Primary(emem_fact::PrimaryFact {
            cell: "defi.zb4d9.pefa.zf619".into(),
            band: "copdem30m.elevation_mean".into(),
            tslot: 0,
            value: ciborium::Value::Float(123.0),
            unit: Some("m".into()),
            confidence: 0.95,
            uncertainty: None,
            sources: vec![Source {
                scheme: "test.bogus".into(),
                id: "test".into(),
                cid: None,
                hash: None,
                captured_at: None,
                url: None,
            }],
            derivation: Derivation {
                fn_key: "test@1".into(),
                args: None,
            },
            privacy_class: "public".into(),
            schema_cid: SchemaCid::new(s.manifests.schema_cid.as_str()),
            signer: s.identity.pubkey,
            signed_at: "2026-05-31T00:00:00Z".into(),
            served_via: None,
        });
        let v_tampered = post_verify_receipt(
            State(s.clone()),
            Ok(Json(VerifyReceiptReq {
                receipt: receipt2,
                pubkey_b32: None,
                current_responder_epoch: None,
                facts: Some(vec![bogus]),
            })),
        )
        .await
        .map_err(|e| format!("verify bogus-fact: {} {}", e.0, e.1.message))
        .unwrap();
        // `valid` reflects the receipt's cryptographic validity ONLY, it is
        // genuine, so valid stays true even though the supplied fact is bogus.
        // The facts cross-check is ADVISORY: a fact not in the receipt's cids
        // surfaces as facts_confirmed:false (never a false `valid:false`, which
        // previously broke the genuine recall→verify path over a JSON round-trip).
        assert_eq!(
            v_tampered.get("valid").and_then(|x| x.as_bool()),
            Some(true),
            "receipt signature is genuine; valid reflects the receipt only: {v_tampered:?}"
        );
        assert_eq!(
            v_tampered.get("facts_confirmed").and_then(|x| x.as_bool()),
            Some(false),
            "a fact not among the receipt's cids must surface facts_confirmed:false: {v_tampered:?}"
        );
        let in_receipt = v_tampered
            .get("facts_check")
            .and_then(|x| x.as_array())
            .and_then(|a| a.first())
            .and_then(|e| e.get("in_receipt"))
            .and_then(|b| b.as_bool());
        assert_eq!(
            in_receipt,
            Some(false),
            "the bogus fact's recomputed cid is not in the receipt: {v_tampered:?}"
        );
    }

