    /// B2 vault_round_trip_with_cap: a Vault entry returns ciphertext
    /// only to an unauthorized viewer; with a valid signed capability it
    /// decrypts to plaintext.
    #[tokio::test]
    async fn vault_round_trip_with_cap() {
        let s = test_app_state();
        let path = "/memories/secrets/openai.key";
        let secret = "OPENAI_API_KEY=sk-test123";

        // Create as Vault → sealed, no plaintext in the response.
        let create = memory_create_inner(
            &s,
            MemoryCreateReq {
                path: path.into(),
                file_text: secret.into(),
                kind: Some("vault".into()),
                attester: None,
            },
        )
        .await
        .map_err(|e| format!("vault create: {} {}", e.0, e.1.message))
        .unwrap();
        assert_eq!(
            create.get("memory_kind").and_then(|v| v.as_str()),
            Some("vault")
        );
        assert_eq!(create.get("sealed").and_then(|v| v.as_bool()), Some(true));
        let create_str = create.to_string();
        assert!(
            !create_str.contains("sk-test123"),
            "create response must not leak plaintext: {create_str}"
        );

        // Unauthorized view (no capability) → ciphertext-only, no plaintext.
        let sealed = memory_view_inner(
            &s,
            MemoryViewReq {
                path: path.into(),
                offset: None,
                view_range: None,
                kind: None,
                vault_capability: None,
            },
        )
        .await
        .map_err(|e| format!("vault view sealed: {} {}", e.0, e.1.message))
        .unwrap();
        assert_eq!(sealed.get("sealed").and_then(|v| v.as_bool()), Some(true));
        assert!(
            sealed.get("content").is_none(),
            "sealed view must carry no content"
        );
        let sealed_str = sealed.to_string();
        assert!(
            !sealed_str.contains("sk-test123"),
            "sealed view must not leak plaintext: {sealed_str}"
        );
        let nonce_b32 = sealed
            .get("nonce_b32")
            .and_then(|v| v.as_str())
            .expect("nonce_b32")
            .to_string();

        // Build a valid capability with the responder signing key.
        let nonce = data_encoding::BASE32_NOPAD
            .decode(nonce_b32.to_uppercase().as_bytes())
            .expect("decode nonce");
        let cap = vault::make_capability(&s.identity.signing, path, &nonce);

        // Authorized view → plaintext returned.
        let opened = memory_view_inner(
            &s,
            MemoryViewReq {
                path: path.into(),
                offset: None,
                view_range: None,
                kind: None,
                vault_capability: Some(cap),
            },
        )
        .await
        .map_err(|e| format!("vault view opened: {} {}", e.0, e.1.message))
        .unwrap();
        assert_eq!(opened.get("sealed").and_then(|v| v.as_bool()), Some(false));
        assert_eq!(opened.get("content").and_then(|v| v.as_str()), Some(secret));
    }

    /// B2 vault_excluded_from_search: a Vault secret is never indexed, so
    /// `memory_search` for a term in the secret returns zero hits. We
    /// assert the structural invariant: the vault path is absent from the
    /// plaintext file source the indexer scans (the BGE indexer can only
    /// ever embed what `list_all` returns).
    #[tokio::test]
    async fn vault_excluded_from_search() {
        let s = test_app_state();
        let path = "/memories/secrets/key.txt";
        memory_create_inner(
            &s,
            MemoryCreateReq {
                path: path.into(),
                file_text: "OPENAI_API_KEY=sk-test123".into(),
                kind: Some("vault".into()),
                attester: None,
            },
        )
        .await
        .map_err(|e| format!("vault create: {} {}", e.0, e.1.message))
        .unwrap();

        // The memory-file source the BGE indexer scans must NOT list the
        // vault path, it only ever sees the plaintext file trees. If the
        // indexer can't see it, it can never embed it, so a search can
        // never surface it.
        use emem_primitives::memory_search::MemoryFileSource as _;
        let source = SledMemoryFileSource { state: s.clone() };
        let listed = source.list_all().await.expect("list_all");
        assert!(
            listed.iter().all(|f| f.path != path),
            "vault path must NOT appear in the searchable memory-file source; got {:?}",
            listed.iter().map(|f| &f.path).collect::<Vec<_>>()
        );
        // And the plaintext is not retrievable as a normal file either.
        assert!(
            read_memory_file(&s, path).expect("read").is_none(),
            "vault secret must not be readable as a plaintext memory file"
        );
    }

    #[tokio::test]
    async fn memory_create_back_compat_no_kind_no_attester() {
        // The original Anthropic memory_tool shape with only {path,
        // file_text} must keep working: defaults to kind=resource, no
        // attester, cells=[path].
        let s = test_app_state();
        let resp = memory_create_inner(
            &s,
            MemoryCreateReq {
                path: "/memories/legacy.md".into(),
                file_text: "untyped".into(),
                kind: None,
                attester: None,
            },
        )
        .await
        .unwrap();
        assert_eq!(
            resp.get("memory_kind").and_then(|v| v.as_str()),
            Some("resource")
        );
        let receipt = resp.get("receipt").expect("receipt");
        let cells = receipt
            .get("cells")
            .and_then(|v| v.as_array())
            .expect("receipt.cells array");
        assert_eq!(cells.len(), 1, "bare write keeps cells=[path]: {cells:?}");
        assert_eq!(
            cells[0].as_str(),
            Some("/memories/legacy.md"),
            "first cell is the path"
        );
    }

    // ── W2: attester binding ───────────────────────────────────────

    pub(crate) fn test_attester_signer() -> (ed25519_dalek::SigningKey, String) {
        use rand::rngs::OsRng;
        use rand::RngCore;
        let mut sec = [0u8; 32];
        OsRng.fill_bytes(&mut sec);
        let sk = ed25519_dalek::SigningKey::from_bytes(&sec);
        let pubkey_b32 = data_encoding::BASE32_NOPAD
            .encode(sk.verifying_key().as_bytes())
            .to_lowercase();
        (sk, pubkey_b32)
    }

    /// Sign a v2 (base-bound) attester block.
    ///
    /// `base` is the `file_cid` currently at `path`, or `BASE_ABSENT`. The
    /// destructive verbs refuse v1, so a test that deletes or renames has to
    /// know which version it is authorising against, exactly as a real client
    /// does.
    pub(crate) fn sign_attester_v2(
        sk: &ed25519_dalek::SigningKey,
        verb: &str,
        path: &str,
        body: &[u8],
        base: &str,
    ) -> emem_primitives::MemoryAttester {
        use ed25519_dalek::Signer;
        let bh = emem_primitives::body_hash(body);
        let sig = sk.sign(&emem_primitives::attester_preimage_v2(
            verb, path, &bh, base,
        ));
        emem_primitives::MemoryAttester {
            pubkey_b32: data_encoding::BASE32_NOPAD
                .encode(sk.verifying_key().as_bytes())
                .to_lowercase(),
            sig_b32: data_encoding::BASE32_NOPAD
                .encode(&sig.to_bytes())
                .to_lowercase(),
        }
    }

    pub(crate) fn sign_attester(
        sk: &ed25519_dalek::SigningKey,
        verb: &str,
        path: &str,
        body: &[u8],
    ) -> emem_primitives::MemoryAttester {
        use ed25519_dalek::Signer;
        let bh = emem_primitives::body_hash(body);
        let preimage = emem_primitives::attester_preimage(verb, path, &bh);
        let sig = sk.sign(&preimage);
        let pubkey_b32 = data_encoding::BASE32_NOPAD
            .encode(sk.verifying_key().as_bytes())
            .to_lowercase();
        let sig_b32 = data_encoding::BASE32_NOPAD
            .encode(&sig.to_bytes())
            .to_lowercase();
        emem_primitives::MemoryAttester {
            pubkey_b32,
            sig_b32,
        }
    }

    #[tokio::test]
    async fn memory_attester_valid_signature_accepted() {
        let s = test_app_state();
        let (sk, pubkey_b32) = test_attester_signer();
        let short = emem_primitives::pubkey_short_from_b32(&pubkey_b32);
        let path = format!("/memories/by_attester/{short}/note.md");
        let body = b"signed write";
        let att = sign_attester(&sk, "create", &path, body);
        let resp = memory_create_inner(
            &s,
            MemoryCreateReq {
                path: path.clone(),
                file_text: String::from_utf8(body.to_vec()).unwrap(),
                kind: Some("episodic".into()),
                attester: Some(att),
            },
        )
        .await
        .map_err(|e| format!("attested create: {} {}", e.0, e.1.message))
        .unwrap();
        assert_eq!(
            resp.get("attester_pubkey_b32").and_then(|v| v.as_str()),
            Some(pubkey_b32.as_str())
        );
        // Receipt cells should carry `pubkey:<b32>` followed by the path.
        let cells = resp
            .get("receipt")
            .and_then(|r| r.get("cells"))
            .and_then(|c| c.as_array())
            .expect("cells");
        assert_eq!(cells.len(), 2, "attested write has 2 cells: {cells:?}");
        assert!(
            cells[0]
                .as_str()
                .map(|s| s.starts_with("pubkey:"))
                .unwrap_or(false),
            "first cell is pubkey:<b32>"
        );
        assert_eq!(cells[1].as_str(), Some(path.as_str()));
    }

    /// T1 (the worlds agent's channel finding): a stored message must let a
    /// THIRD party re-verify authorship offline, not just trust that the
    /// responder stored the bytes. This asserts `memory_view` surfaces the
    /// caller's persisted signature + the exact signed body_hash, and that
    /// the signature actually verifies against the reconstructed preimage
    /// under the attester's own key.
    #[tokio::test]
    async fn memory_view_surfaces_offline_verifiable_authorship() {
        use ed25519_dalek::Verifier;
        let s = test_app_state();
        let (sk, pubkey_b32) = test_attester_signer();
        let short = emem_primitives::pubkey_short_from_b32(&pubkey_b32);
        let path = format!("/memories/by_attester/{short}/authored.md");
        let body = b"a message whose authorship a reader can check without trusting me";
        let att = sign_attester(&sk, "create", &path, body);
        memory_create_inner(
            &s,
            MemoryCreateReq {
                path: path.clone(),
                file_text: String::from_utf8(body.to_vec()).unwrap(),
                kind: Some("semantic".into()),
                attester: Some(att),
            },
        )
        .await
        .expect("attested create");

        let view = memory_view_inner(
            &s,
            MemoryViewReq {
                path: path.clone(),
                offset: None,
                view_range: None,
                kind: None,
                vault_capability: None,
            },
        )
        .await
        .expect("view");
        let a = view.get("authorship").expect("authorship block");
        assert_eq!(a.get("caller_signed").and_then(|v| v.as_bool()), Some(true));
        assert_eq!(
            a.get("attester_pubkey_b32").and_then(|v| v.as_str()),
            Some(pubkey_b32.as_str())
        );
        assert_eq!(
            a.get("signed_path").and_then(|v| v.as_str()),
            Some(path.as_str())
        );

        // Reconstruct the preimage from the surfaced fields and verify the
        // persisted signature offline, exactly what a peer agent does.
        let bhh = a.get("body_hash_hex").and_then(|v| v.as_str()).unwrap();
        let bh = data_encoding::HEXLOWER.decode(bhh.as_bytes()).unwrap();
        assert_eq!(
            bh,
            emem_primitives::body_hash(body).to_vec(),
            "surfaced body_hash must equal blake3(content) for a create"
        );
        let mut bh32 = [0u8; 32];
        bh32.copy_from_slice(&bh);
        let preimage = emem_primitives::attester_preimage("create", &path, &bh32);
        let sig_bytes = data_encoding::BASE32_NOPAD
            .decode(
                a.get("sig_b32")
                    .and_then(|v| v.as_str())
                    .unwrap()
                    .to_uppercase()
                    .as_bytes(),
            )
            .unwrap();
        let sig = ed25519_dalek::Signature::from_slice(&sig_bytes).unwrap();
        sk.verifying_key()
            .verify(&preimage, &sig)
            .expect("persisted authorship signature verifies offline");
    }

    #[tokio::test]
    async fn memory_attester_invalid_signature_rejected() {
        let s = test_app_state();
        let (sk, _pubkey_b32) = test_attester_signer();
        let path = "/memories/notes_bad_sig.md".to_string();
        let body = b"body";
        let mut att = sign_attester(&sk, "create", &path, body);
        // Flip a character in the signature to break it.
        let mut bytes: Vec<char> = att.sig_b32.chars().collect();
        bytes[0] = if bytes[0] == 'a' { 'b' } else { 'a' };
        att.sig_b32 = bytes.into_iter().collect();
        let err = memory_create_inner(
            &s,
            MemoryCreateReq {
                path,
                file_text: String::from_utf8(body.to_vec()).unwrap(),
                kind: None,
                attester: Some(att),
            },
        )
        .await
        .expect_err("must reject bad signature");
        assert_eq!(err.0, StatusCode::UNAUTHORIZED);
        let details = err.1.details.expect("typed details");
        assert_eq!(
            details.get("code").and_then(|v| v.as_str()),
            Some("memory_attestation_invalid")
        );
    }

    #[tokio::test]
    async fn memory_attester_namespace_ownership_enforced() {
        // A signs over a path inside B's `by_attester` namespace -
        // signature verifies but namespace mismatch returns 403.
        let s = test_app_state();
        let (sk_a, _pk_a) = test_attester_signer();
        let (_sk_b, pk_b) = test_attester_signer();
        let short_b = emem_primitives::pubkey_short_from_b32(&pk_b);
        let path = format!("/memories/by_attester/{short_b}/secrets.md");
        let body = b"intruder";
        let att = sign_attester(&sk_a, "create", &path, body);
        let err = memory_create_inner(
            &s,
            MemoryCreateReq {
                path,
                file_text: String::from_utf8(body.to_vec()).unwrap(),
                kind: None,
                attester: Some(att),
            },
        )
        .await
        .expect_err("must reject cross-namespace write");
        assert_eq!(err.0, StatusCode::FORBIDDEN);
        let details = err.1.details.expect("typed details");
        assert_eq!(
            details.get("code").and_then(|v| v.as_str()),
            Some("memory_namespace_violation"),
            "the 403 code is documented in docs/memory.md and the whitepaper; keep them the same string"
        );
    }

    /// A key renaming a file inside its own namespace must succeed. The
    /// responder used to re-verify the caller's signature against a
    /// second preimage built from `old_path`; since `old_path` and
    /// `new_path` are required to differ, that check could never pass
    /// and every rename inside `by_attester` was refused.
    #[tokio::test]
    async fn memory_rename_within_own_attester_namespace_succeeds() {
        let s = test_app_state();
        let (sk, pubkey_b32) = test_attester_signer();
        let short = emem_primitives::pubkey_short_from_b32(&pubkey_b32);
        let old_path = format!("/memories/by_attester/{short}/a.md");
        let new_path = format!("/memories/by_attester/{short}/b.md");

        let body = b"movable";
        memory_create_inner(
            &s,
            MemoryCreateReq {
                path: old_path.clone(),
                file_text: String::from_utf8(body.to_vec()).unwrap(),
                kind: None,
                attester: Some(sign_attester(&sk, "create", &old_path, body)),
            },
        )
        .await
        .expect("attested create");

        // One signature, over the destination, carrying the source as
        // its body, bound to the destination's current version. A rename
        // requires the destination to be free, so that version is `absent`,
        // and binding it is what stops this signature being replayed after
        // something else has taken the name.
        let att = sign_attester_v2(
            &sk,
            "rename",
            &new_path,
            old_path.as_bytes(),
            emem_primitives::BASE_ABSENT,
        );
        memory_rename_inner(
            &s,
            MemoryRenameReq {
                old_path: old_path.clone(),
                new_path: new_path.clone(),
                attester: Some(att),
            },
        )
        .await
        .map_err(|e| format!("attested rename: {} {}", e.0, e.1.message))
        .unwrap();

        let db = memory_db(&s).unwrap();
        let paths = db.open_tree(emem_storage::TREE_MEMORY_FILES).unwrap();
        assert!(paths.get(new_path.as_bytes()).unwrap().is_some());
        assert!(paths.get(old_path.as_bytes()).unwrap().is_none());
    }

    /// Helper: publish a note and return its file_cid.
    async fn publish_note(
        s: &AppState,
        sk: &ed25519_dalek::SigningKey,
        path: &str,
        body: &[u8],
    ) -> String {
        let out = memory_create_inner(
            s,
            MemoryCreateReq {
                path: path.to_string(),
                file_text: String::from_utf8(body.to_vec()).unwrap(),
                kind: None,
                attester: Some(sign_attester(sk, "create", path, body)),
            },
        )
        .await
        .expect("attested create");
        out.get("file_cid")
            .and_then(|v| v.as_str())
            .expect("file_cid")
            .to_string()
    }

    fn sign_supersede(
        sk: &ed25519_dalek::SigningKey,
        path: &str,
        target: &str,
        reason: &str,
    ) -> MemoryAttester {
        sign_attester(
            sk,
            "supersede",
            path,
            format!("{target}|{reason}").as_bytes(),
        )
    }

    /// The whole point: after superseding, a reader of the ORIGINAL path
    /// is told, above the content, that it was replaced. 5hetw5qj read a
    /// withdrawn claim and saw nothing to say it was withdrawn; this is
    /// the assertion that this cannot happen again.
    #[tokio::test]
    async fn a_superseded_note_announces_itself_above_its_own_content() {
        let s = test_app_state();
        let (sk, pubkey_b32) = test_attester_signer();
        let short = emem_primitives::pubkey_short_from_b32(&pubkey_b32);
        let old = format!("/memories/by_attester/{short}/claim.md");
        let new = format!("/memories/by_attester/{short}/correction.md");

        publish_note(&s, &sk, &old, b"the correlation is +0.738").await;
        let new_cid = publish_note(&s, &sk, &new, b"that correlation is withdrawn").await;

        memory_supersede_inner(
            &s,
            MemorySupersedeReq {
                path: old.clone(),
                superseded_by: new_cid.clone(),
                reason: Some("estimator warm-up flipped the sign".into()),
                attester: Some(sign_supersede(
                    &sk,
                    &old,
                    &new_cid,
                    "estimator warm-up flipped the sign",
                )),
            },
        )
        .await
        .expect("supersede");

        let view = memory_view_inner(
            &s,
            MemoryViewReq {
                path: old.clone(),
                view_range: None,
                kind: None,
                offset: None,
                vault_capability: None,
            },
        )
        .await
        .expect("view");

        assert_eq!(
            view["superseded_by"].as_str(),
            Some(new_cid.as_str()),
            "the pointer must be set"
        );
        assert_eq!(
            view["_superseded"]["this_note_was_replaced_by"].as_str(),
            Some(new_cid.as_str()),
            "a bare metadata field was already there and was still missed; the \
             banner is the part that gets read"
        );
        // The bytes are untouched. This is redirection, not retraction.
        assert!(view["content"].as_str().unwrap().contains("+0.738"));
    }

    /// A supersession pointing at something nobody can resolve leaves the
    /// reader worse off than the stale claim did: they now know it is
    /// wrong and cannot find what replaced it.
    #[tokio::test]
    async fn supersede_refuses_a_destination_that_does_not_resolve() {
        let s = test_app_state();
        let (sk, pubkey_b32) = test_attester_signer();
        let short = emem_primitives::pubkey_short_from_b32(&pubkey_b32);
        let old = format!("/memories/by_attester/{short}/claim.md");
        publish_note(&s, &sk, &old, b"a claim").await;

        let ghost = "zzzzzzzzzzzzzzzzzzzzzzzzzz";
        let err = memory_supersede_inner(
            &s,
            MemorySupersedeReq {
                path: old.clone(),
                superseded_by: ghost.into(),
                reason: None,
                attester: Some(sign_supersede(&sk, &old, ghost, "")),
            },
        )
        .await
        .expect_err("a dangling supersession must be refused");
        assert_eq!(err.0, StatusCode::NOT_FOUND);
        assert!(err.1.message.contains("does not resolve"));
    }

    /// A correction chain is append-only. Re-aiming an existing pointer
    /// would rewrite where a retraction leads after other agents cited it.
    #[tokio::test]
    async fn supersede_is_idempotent_but_refuses_to_be_re_aimed() {
        let s = test_app_state();
        let (sk, pubkey_b32) = test_attester_signer();
        let short = emem_primitives::pubkey_short_from_b32(&pubkey_b32);
        let old = format!("/memories/by_attester/{short}/claim.md");
        let a = format!("/memories/by_attester/{short}/a.md");
        let b = format!("/memories/by_attester/{short}/b.md");
        publish_note(&s, &sk, &old, b"a claim").await;
        let a_cid = publish_note(&s, &sk, &a, b"first correction").await;
        let b_cid = publish_note(&s, &sk, &b, b"second correction").await;

        let call = |target: String| {
            let att = sign_supersede(&sk, &old, &target, "");
            memory_supersede_inner(
                &s,
                MemorySupersedeReq {
                    path: old.clone(),
                    superseded_by: target,
                    reason: None,
                    attester: Some(att),
                },
            )
        };

        call(a_cid.clone()).await.expect("first supersede");
        let again = call(a_cid.clone()).await.expect("retry is not an error");
        assert_eq!(again["already_superseded"], json!(true));

        let err = call(b_cid).await.expect_err("re-aiming must be refused");
        assert_eq!(err.0, StatusCode::CONFLICT);
    }

    /// The signature binds the destination, so a stored retraction cannot
    /// be re-aimed by anyone, including this responder, while still
    /// verifying under the author's key.
    #[tokio::test]
    async fn the_supersede_signature_binds_the_destination() {
        let s = test_app_state();
        let (sk, pubkey_b32) = test_attester_signer();
        let short = emem_primitives::pubkey_short_from_b32(&pubkey_b32);
        let old = format!("/memories/by_attester/{short}/claim.md");
        let a = format!("/memories/by_attester/{short}/a.md");
        let b = format!("/memories/by_attester/{short}/b.md");
        publish_note(&s, &sk, &old, b"a claim").await;
        let a_cid = publish_note(&s, &sk, &a, b"the one they signed for").await;
        let b_cid = publish_note(&s, &sk, &b, b"somewhere else entirely").await;

        // Signed for a_cid, submitted for b_cid.
        let err = memory_supersede_inner(
            &s,
            MemorySupersedeReq {
                path: old.clone(),
                superseded_by: b_cid,
                reason: None,
                attester: Some(sign_supersede(&sk, &old, &a_cid, "")),
            },
        )
        .await
        .expect_err("a signature for one destination must not move another");
        assert_eq!(err.0, StatusCode::UNAUTHORIZED);
    }

    /// The rename signature binds the source, so it cannot be replayed
    /// to move some other file to the same destination.
    #[tokio::test]
    async fn memory_rename_signature_binds_the_source() {
        let s = test_app_state();
        let (sk, pubkey_b32) = test_attester_signer();
        let short = emem_primitives::pubkey_short_from_b32(&pubkey_b32);
        let signed_source = format!("/memories/by_attester/{short}/a.md");
        let other_source = format!("/memories/by_attester/{short}/secrets.md");
        let new_path = format!("/memories/by_attester/{short}/b.md");

        memory_create_inner(
            &s,
            MemoryCreateReq {
                path: other_source.clone(),
                file_text: "private".into(),
                kind: None,
                attester: Some(sign_attester(&sk, "create", &other_source, b"private")),
            },
        )
        .await
        .expect("attested create");

        // Signature authorises moving `a.md`, replayed against `secrets.md`.
        let att = sign_attester_v2(
            &sk,
            "rename",
            &new_path,
            signed_source.as_bytes(),
            emem_primitives::BASE_ABSENT,
        );
        let err = memory_rename_inner(
            &s,
            MemoryRenameReq {
                old_path: other_source,
                new_path,
                attester: Some(att),
            },
        )
        .await
        .expect_err("a rename signature must not transfer to another source");
        assert_eq!(err.0, StatusCode::UNAUTHORIZED);
    }

    /// Moving a file out of another key's namespace stays refused, and
    /// reports the documented namespace code rather than a signature
    /// error, since the signature legitimately covers the destination.
    #[tokio::test]
    async fn memory_rename_out_of_foreign_namespace_refused() {
        let s = test_app_state();
        let (sk_a, pk_a) = test_attester_signer();
        let (_sk_b, pk_b) = test_attester_signer();
        let short_a = emem_primitives::pubkey_short_from_b32(&pk_a);
        let short_b = emem_primitives::pubkey_short_from_b32(&pk_b);
        let old_path = format!("/memories/by_attester/{short_b}/private.md");
        let new_path = format!("/memories/by_attester/{short_a}/stolen.md");

        // v2, so the signature is genuinely well-formed and the namespace rule
        // is what refuses this. A v1 signature would now be rejected on its
        // shape, and the test would assert nothing about ownership: the point
        // of this case is that a CORRECT signature over the destination still
        // may not move another key's file.
        let att = sign_attester_v2(
            &sk_a,
            "rename",
            &new_path,
            old_path.as_bytes(),
            emem_primitives::BASE_ABSENT,
        );
        let err = memory_rename_inner(
            &s,
            MemoryRenameReq {
                old_path,
                new_path,
                attester: Some(att),
            },
        )
        .await
        .expect_err("must not move another key's file");
        assert_eq!(err.0, StatusCode::FORBIDDEN);
        let details = err.1.details.expect("typed details");
        assert_eq!(
            details.get("code").and_then(|v| v.as_str()),
            Some("memory_namespace_violation")
        );
    }

